window.EVENTS_F=[{"id":"F-001","branch":"F","stage":1,"day":1,"shichen":"辰时","checkpoint":"看榜","scene":"今日你行过笄礼，刚换下礼服，爹便拉你去看榜。人潮挤得慌，你由绣儿扶着在茶棚里远远望。红纸榜文贴满墙，爹踮脚念名字，忽然眼睛一亮：「这顾景行，好名次！」","options":[{"text":"央绣儿去挤看榜文","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"绣儿挤到墙根，回头学那名字笔画给你听。你心里悄悄记下了「顾景行」三字。","source":"榜下捉婿之俗，见《东京梦华录》。"},{"text":"只在茶棚里吃茶","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你安坐吃茶，榜上姓名一概不知。爹回头怪你不上心，你只笑不答。","source":"同上。"}],"difficulty":1,"npc":["爹"],"foreshadow":"红纸榜文"},{"id":"F-001-未","branch":"F","stage":1,"day":1,"shichen":"未时","checkpoint":"相中","scene":"茶棚里爹来回踱步，又望榜墙。他低声盘算：这顾景行籍贯苏州、二甲名次，文章据说极好。他拍腿道：「我程家闺女，配得！」","options":[{"text":"问爹他长相如何","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"爹摇头：「远远哪看得清？只听人说他清癯如竹，眉目疏朗。」你却已浮出个模样。","source":"同上。"},{"text":"劝爹莫急于下定","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你劝慢些，爹瞪眼：「榜下捉婿，慢一步人就没了！」只得由他。","source":"同上。"}],"difficulty":1,"npc":["爹"],"foreshadow":"红纸榜文"},{"id":"F-001-戌","branch":"F","stage":1,"day":1,"shichen":"戌时","checkpoint":"听传闻","scene":"回程轿中，绣儿叽叽喳喳学市井闲话：那顾景行至今未定亲，同榜几家都想「捉」他。你掀帘看汴河灯，心思悄悄飘远。","options":[{"text":"让绣儿细说那人名次","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"绣儿说二甲第三，主考赞他策论有古风。你暗暗点头，榜文上的字便鲜活了。","source":"同上。"},{"text":"吩咐绣儿莫论外人","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你端起架子，绣儿吐舌闭嘴。夜风凉，你倒有些懊悔方才的矜持。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"红纸榜文"},{"id":"F-002","branch":"F","stage":1,"day":2,"shichen":"辰时","checkpoint":"托媒","scene":"翌日天刚亮，爹差人请来张媒婆。爹塞过红纸榜文抄件：「去顾家，说程家愿结这门亲。」媒婆拍胸脯应下，喜气便先上了门。","options":[{"text":"嘱媒婆好生说顾家清寒也无妨","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"媒婆去了。你隔着屏风听爹说：「清寒怕什么，人品文章要紧。」你脸一热。","source":"《东京梦华录·娶妇》。"},{"text":"让爹先探顾家家底","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"爹果然去打听了，回来直咂嘴：顾家确清寒，却家教极好。你反倒更敬。","source":"同上。"}],"difficulty":1,"npc":["爹","张媒婆"],"foreshadow":"红纸榜文"},{"id":"F-002-未","branch":"F","stage":1,"day":2,"shichen":"未时","checkpoint":"推辞","scene":"媒婆晌午回话，面有难色：顾家推了，说顾景行守礼，不愿榜下草草定亲，怕误了程家闺女。爹却来了劲，说这人有骨气。","options":[{"text":"暗暗佩服他推辞的规矩","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你听罢竟生敬意：这人未谋面先守礼，倒比那些抢婿的体面。你偷偷记他字「明远」。","source":"《梦粱录·嫁娶》。"},{"text":"怪顾家不识抬举","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你撇嘴，爹却笑：「有骨气！三顾才显诚心。」你不解，却也息了气。","source":"同上。"}],"difficulty":1,"npc":["张媒婆","爹"],"foreshadow":"顾景行的字"},{"id":"F-002-戌","branch":"F","stage":1,"day":2,"shichen":"戌时","checkpoint":"三顾之始","scene":"夜里爹搓手：头回吃了闭门羹，明日再去。你替他理袍角，听见他念叨「明远、明远」，你忽然想，这名字倒好听。","options":[{"text":"替爹把顾家地址记在笺上","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你提笔抄了地址，顺手描了遍「明远」二字。笺纸轻，心事却重了些。","source":"同上。"},{"text":"劝爹莫再自讨没趣","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你劝歇手，爹瞪你：「闺女你说得轻！好女婿过了这村没这店。」你噗地笑了。","source":"同上。"}],"difficulty":1,"npc":["爹"],"foreshadow":"顾景行的字"},{"id":"F-003","branch":"F","stage":1,"day":3,"shichen":"辰时","checkpoint":"再顾","scene":"爹二顾顾家，带了对蟹与苏合香。顾母出面，仍客气道儿子志在仕途，亲事恐耽搁。爹笑说程家不急，先交个朋友。","options":[{"text":"赞爹这般诚意难得","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你听绣儿学舌，直点头：爹平日抠门，今番倒舍得。你心里替那陌生人松口气。","source":"《东京梦华录·娶妇》。"},{"text":"疑顾家拿乔","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你疑心顾家摆谱，绣儿却道顾母说话诚恳。你半信半疑，且看下回。","source":"同上。"}],"difficulty":1,"npc":["爹","张媒婆"],"foreshadow":"顾景行的字"},{"id":"F-003-未","branch":"F","stage":1,"day":3,"shichen":"未时","checkpoint":"拼凑","scene":"绣儿从外头听来：顾景行苏州人，二甲第三，策论受主考激赏。同榜几家放风要捉他，他却躲了清净，不凑热闹。","options":[{"text":"让绣儿再说他文章好在哪","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"绣儿学舌：说他论漕运一篇，考官批「有社稷心」。你默念，这人倒不只是好看。","source":"《宋史·选举志》。"},{"text":"只问旁人是否也抢他","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"绣儿说抢的人多。你轻哼：那便更得抓紧。话出口又觉失态，忙捂嘴。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"顾景行的字"},{"id":"F-003-戌","branch":"F","stage":1,"day":3,"shichen":"戌时","checkpoint":"篦发夜话","scene":"戌时灯下，绣儿替你篦发，讲市井又说顾家清寒，顾景行却不肯受无功之惠，推亲事是为不误程家。你听得分明，心口微动。","options":[{"text":"叹他竟替未谋面的人打算","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你低声叹：这人连没见过面的姑娘都体恤。绣儿瞅你：姑娘这是夸人呢。你耳根热了。","source":"《梦粱录·嫁娶》。"},{"text":"疑他推辞是嫌程家","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你疑他嫌弃，绣儿急辩：他连庚帖都未换便推，分明是怕耽误。你一想，倒惭愧。","source":"同上。"}],"difficulty":2,"npc":["绣儿"],"foreshadow":"顾景行的字"},{"id":"F-004","branch":"F","stage":1,"day":4,"shichen":"辰时","checkpoint":"三顾","scene":"爹三顾顾家，这回顾景行亲自出面，揖礼深长，谢程家错爱，却仍说功名未立，不敢匆忙定亲。爹大笑：正该如此！","options":[{"text":"赞他亲面致谢的礼数","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你隔窗望见那道揖礼的影，虽看不清眉眼，却觉这人稳当。你第一次想看清他。","source":"《仪礼·士昏礼》。"},{"text":"怪他磨蹭不见真章","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你嫌他只推不见真章，爹却道：肯亲自见媒，已是给面子。你嘟囔，心里却松。","source":"同上。"}],"difficulty":1,"npc":["爹","张媒婆"],"foreshadow":"红纸榜文"},{"id":"F-004-未","branch":"F","stage":1,"day":4,"shichen":"未时","checkpoint":"悬念","scene":"绣儿探得实情：顾景行并非无人说亲，是他在籍时母丧未远，守制清简，不愿热闹定亲。你这才知道他迟迟未定的缘故。","options":[{"text":"敬他守制持重","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你心里那点猜疑散了：原是孝子。你默念「明远」，觉这二字更熨帖了。","source":"《宋史·礼志》。"},{"text":"担心守制误了亲事","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你急他守制误事，绣儿笑：制已满，只是人谨慎。你松口气，暗怪自己沉不住气。","source":"同上。"}],"difficulty":2,"npc":["绣儿"],"foreshadow":"顾景行的字"},{"id":"F-004-戌","branch":"F","stage":1,"day":4,"shichen":"戌时","checkpoint":"娘来探","scene":"戌时娘来厢房，替你掖被，低声道：你爹相中的人，听着不错。你装睡，却听娘笑：闺女心跳得比我还响。","options":[{"text":"应下娘的打趣","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你睁眼嘟囔：娘莫取笑。娘说好女婿急不得，你点头，把「明远」二字藏进枕头边。","source":"《礼记·内则》。"},{"text":"问娘顾家清寒可好","correct":true,"tags":["家世","感情"],"dims":{"家世":1},"feedback":"你问娘顾家清寒可好，娘道人品比银钱金贵。你安心闭眼，梦里竟见一袭青衫。","source":"同上。"}],"difficulty":2,"npc":["娘"],"foreshadow":"顾景行的字","flavor":true},{"id":"F-005","branch":"F","stage":1,"day":5,"shichen":"辰时","checkpoint":"长相","scene":"绣儿今日绘声绘色：顾景行清癯如竹，眉目疏朗，说话慢声细语，同榜都叫他「明远兄」。你听得入了神。","options":[{"text":"让绣儿学他说话模样","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"绣儿捏着嗓子学他温言，你笑出声，又忙掩口。那未见的面容，竟一日比一日清晰。","source":"《东京梦华录》。"},{"text":"笑绣儿编排太过","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你笑她添油加醋，绣儿不服：多少人见过哩。你半信，倒盼她说得更真些。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"顾景行的字"},{"id":"F-005-未","branch":"F","stage":1,"day":5,"shichen":"未时","checkpoint":"诗风","scene":"绣儿又说，顾景行闲时以诗会友，同窗索诗他便写，从不藏私。你忽然想，若得他一字，该多好。","options":[{"text":"默记下他爱写田园小诗","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你暗记他诗风清淡，像人一般。绣儿问要不要也学写，你啐她，笔下却描了句。","source":"宋代笔记。"},{"text":"疑诗作是他人代笔","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你疑心才名虚的，绣儿急：主考亲批的策论呢！你一想有理，倒更敬了几分。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"诗笺"},{"id":"F-005-戌","branch":"F","stage":1,"day":5,"shichen":"戌时","checkpoint":"夜思","scene":"戌时你独坐窗前，汴河灯影摇动。你裁了张素笺，想临他的诗风写两句，又羞，终是只写了「明远」二字收好。","options":[{"text":"将素笺收进妆奁","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你把写他字的笺压在奁底，像藏个小秘密。绣儿撞见，你红着脸说只是练字。","source":"同上。"},{"text":"揉了素笺怕人瞧见","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你慌张揉掉，怕绣儿取笑。夜深了，却又懊恼没留住那两字，翻来覆去睡不着。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"诗笺"},{"id":"F-006","branch":"F","stage":1,"day":6,"shichen":"辰时","checkpoint":"爹定调","scene":"爹回来说定：顾家虽推，却收了程家名帖，算是留了话。爹拍你肩：闺女，这人爹替你盯着，错不了。","options":[{"text":"应下爹的好意","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你低头应了声「嗯」，没敢抬眼。爹乐呵呵去喝酒，你却把那二字又念了一遍。","source":"《东京梦华录·娶妇》。"},{"text":"嘴硬说全凭爹主张","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你嘴硬：全凭爹。爹笑你口是心非，你转身跑开，心跳却出卖了自己。","source":"同上。"}],"difficulty":1,"npc":["爹"],"foreshadow":"顾景行的字"},{"id":"F-006-未","branch":"F","stage":1,"day":6,"shichen":"未时","checkpoint":"诗笺伏笔","scene":"绣儿献宝：她求得顾景行赠友的一首小诗抄本，字迹疏朗。你借来看，纸上墨淡，却句句清雅，像极了传闻中人。","options":[{"text":"悄悄临了一遍他的字","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你铺纸临他的字，笔锋竟也柔和下来。绣儿笑：姑娘这字，近日格外好看。你脸一红。","source":"宋代笔记。"},{"text":"只赏诗不学字","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你只读诗不临写，赞他「有林下风」。绣儿撇嘴：不学字怎知他筋骨。你笑她门道多。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"诗笺"},{"id":"F-006-戌","branch":"F","stage":1,"day":6,"shichen":"戌时","checkpoint":"夜展诗","scene":"戌时灯下你又展那诗抄，忽觉纸上似有淡淡墨香。绣儿说新科进士皆以诗笺往来，你心想，若有一日他愿赠我……","options":[{"text":"把诗抄妥帖收好","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你将诗抄夹进书页，像护着件宝贝。夜风过，你竟盼着六礼早些走到跟前。","source":"同上。"},{"text":"求绣儿再去讨一首","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你贪心要绣儿再讨，绣儿为难：哪能白讨。你讪讪止了，倒觉自己孟浪。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"诗笺"},{"id":"F-007","branch":"F","stage":1,"day":7,"shichen":"辰时","checkpoint":"顾家回话","scene":"媒婆传话：顾家松了口，说待守制诸事毕，愿与程家从纳采议起。爹喜得赏了媒婆一对金镯，满院喜气。","options":[{"text":"暗喜这门亲事有谱","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你听罢抿嘴笑，又忙正色。绣儿说姑娘笑得像偷枣，你追着她满院跑。","source":"《梦粱录·嫁娶》。"},{"text":"疑顾家拖延","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你疑他家拿乔拖延，爹笑：肯定六礼就是诚意。你一想，倒觉得自己多心。","source":"同上。"}],"difficulty":2,"npc":["张媒婆","爹"],"foreshadow":"顾景行的字"},{"id":"F-007-未","branch":"F","stage":1,"day":7,"shichen":"未时","checkpoint":"备雁","scene":"娘翻箱说纳采得备雁，活雁难寻，便以雁形礼器代。爹嘟囔银钱，娘瞪他：闺女大事，雁币之礼马虎不得。","options":[{"text":"帮娘挑雁形礼器","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你挑了只青瓷雁，温润如玉。娘夸你有眼力，你心想这雁替那人先上了门。","source":"《仪礼·士昏礼》。"},{"text":"劝娘从简","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你劝省些，娘不依：礼不可废。你笑爹平日抠，今儿倒站娘这边，有趣得紧。","source":"同上。"}],"difficulty":1,"npc":["娘","爹"],"foreshadow":"雁"},{"id":"F-007-戌","branch":"F","stage":1,"day":7,"shichen":"戌时","checkpoint":"雁先上门","scene":"戌时娘坐你榻边，说纳采那日你不必露面，由媒人与爹张罗。你却忽然想，那雁到了顾家，也算替你先拜见了他。","options":[{"text":"把青瓷雁又擦了一遍","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你偷偷把那雁擦得锃亮，像要把自己的心意也擦进去。娘瞧见只笑不说话。","source":"同上。"},{"text":"问娘纳采可否偷看","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你问能否偷瞧，娘正色：闺女家守范，岂可妄动。你吐舌，却更盼那日早来。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"雁"},{"id":"F-008","branch":"F","stage":1,"day":8,"shichen":"辰时","checkpoint":"纳采前夕","scene":"纳采前一日，爹与媒婆对礼单：雁币、束帛、合欢酒。媒婆叮嘱明日辰时出门，莫误了吉时，院里里外外张罗。","options":[{"text":"记下令雁为首礼","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你默念雁为先，像那人要先向你家行个礼。绣儿笑你魔怔，你由她笑去。","source":"《仪礼·士昏礼》。"},{"text":"查礼单可省哪项","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你翻礼单想省，爹敲你头：六礼之始，省一样都不成。你缩脖，老实了。","source":"同上。"}],"difficulty":1,"npc":["爹","张媒婆"],"foreshadow":"雁"},{"id":"F-008-未","branch":"F","stage":1,"day":8,"shichen":"未时","checkpoint":"妆奁念想","scene":"娘拿出你幼时绣的并蒂莲香囊，说纳征时添进奁里。你记得那是我闲时乱绣，针脚歪斜，却绣得极用心。","options":[{"text":"把香囊又补了针脚","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你挑灯补那并蒂莲，针脚虽歪，心意却满。娘说这香囊，迟早随你过去那边。","source":"《梦粱录·嫁娶》。"},{"text":"笑自己绣得丑","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你笑针脚丑，娘却珍重收起：丑也好，是你亲手。你鼻酸，原来娘都记着。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"并蒂莲香囊"},{"id":"F-008-戌","branch":"F","stage":1,"day":8,"shichen":"戌时","checkpoint":"箱笼轻响","scene":"戌时绣儿帮你收奁，捧着并蒂莲香囊叽喳：姑娘这是早早备下陪嫁哩。你拧她腮，灯下两人笑作一团，箱笼轻响。","options":[{"text":"把香囊系在腕上试了试","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你由她取笑，把香囊系在腕上试了试，倒真好看。绣儿说姑娘盼着呢，你装睡不理。","source":"《礼记》。"},{"text":"说奁中物自己说了算","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"你说奁中物自己说了算，绣儿笑你主见大。你知这主见，原是向着那未谋面的人。","source":"同上。"}],"difficulty":2,"npc":["绣儿"],"foreshadow":"并蒂莲香囊","flavor":true},{"id":"F-009","branch":"F","stage":1,"day":9,"shichen":"辰时","checkpoint":"纳采行礼","scene":"辰时媒人携青瓷雁上门，行纳采之礼，口称「敢纳采」。爹受礼答「某不敢辞」。院内喜气悄悄漫开，你立在帘后。","options":[{"text":"隔帘望那青瓷雁","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你隔帘望见那雁安稳立于盘中，像那人妥帖的性子。你悄悄福了福，谁也没瞧见。","source":"《仪礼·士昏礼》。"},{"text":"只听礼不瞧","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你端坐不听不看，绣儿却偷瞧回来说雁极精神。你轻哼，耳根却红了。","source":"同上。"}],"difficulty":2,"npc":["张媒婆","爹"],"foreshadow":"雁"},{"id":"F-009-未","branch":"F","stage":1,"day":9,"shichen":"未时","checkpoint":"顾家回帖","scene":"媒婆回说顾家受雁，回了个素帖致谢，字极工整。你讨来看，帖上无多话，只「谨领，感荷」四字，清简却有分量。","options":[{"text":"把素帖收进书页","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你将那素帖夹进旧书，像收了他半句话。绣儿笑你宝贝兮兮，你由她笑。","source":"宋代笔记。"},{"text":"嫌回帖太薄","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你嫌回帖单薄，绣儿道人家清寒知礼，四字千斤。你一想，倒羞自己浅。","source":"同上。"}],"difficulty":1,"npc":["张媒婆"],"foreshadow":"诗笺"},{"id":"F-009-戌","branch":"F","stage":1,"day":9,"shichen":"戌时","checkpoint":"夜盼问名","scene":"戌时娘说纳采已成，下一步是问名换庚帖。你摸着那素帖，忽然觉六礼像一条慢慢铺好的路，尽头有个人等着。","options":[{"text":"盼着问名那日","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你低声说想快些问名，娘笑：急什么，路要一步一步走。你点头，却忍不住望窗外。","source":"《梦粱录·嫁娶》。"},{"text":"问娘可会换错庚帖","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你杞人忧天怕换错帖，娘笑你书读歪了。你讪讪，倒踏实了些。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"诗笺"},{"id":"F-010","branch":"F","stage":1,"day":10,"shichen":"辰时","checkpoint":"问名前","scene":"爹催媒婆拟庚帖：程家阿盈，庚辰年生，三月十五。媒婆说顾家也要回帖，两庚相换方算问名成，笔砚早备下了。","options":[{"text":"默念自己庚帖上写什么","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你念叨自己的生辰，想他帖上也该有同样字句。绣儿说姑娘念经呢，你追着打。","source":"《仪礼·士昏礼》。"},{"text":"怪爹把生辰说得响","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你嫌爹嚷得满街知，爹笑：正经亲事怕什么。你捂脸，由他去乐。","source":"同上。"}],"difficulty":1,"npc":["爹","张媒婆"],"foreshadow":"庚帖"},{"id":"F-010-未","branch":"F","stage":1,"day":10,"shichen":"未时","checkpoint":"合婚","scene":"娘请算命先生合八字，说程顾二字，金水相生，是大吉。你本不信这些，听娘说得真切，也暗暗欢喜起来。","options":[{"text":"信这桩合婚之喜","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你虽嘴上不信，心里却甜：金水相生，像极了两人和气。娘看你出神，偷笑。","source":"《梦粱录·嫁娶》。"},{"text":"笑娘太迷信","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你笑娘迷信，娘佯怒：你这丫头，吉兆也堵你嘴？你忙讨饶，心里却也受用。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"庚帖"},{"id":"F-010-戌","branch":"F","stage":1,"day":10,"shichen":"戌时","checkpoint":"叠方胜","scene":"戌时绣儿抱来两卷庚帖样纸，说问名那日要互换。你抚着样纸，想那头也有双手，正写着同样的字。","options":[{"text":"把庚帖样纸叠成方胜","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你将样纸折成方胜，藏在枕下。绣儿说姑娘手巧，你笑：是心里巧。","source":"宋代笔记。"},{"text":"查庚帖写法可改","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你想改两笔生辰，绣儿急拦：庚帖岂可乱改！你吐舌，知自己胡闹。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"庚帖"},{"id":"F-011","branch":"F","stage":2,"day":11,"shichen":"辰时","checkpoint":"问名行礼","scene":"辰时媒人携程家庚帖往顾家问名，顾家回帖上写：顾景行，字明远，庚午年生，八月廿二。你终见他全名款。","options":[{"text":"把两庚帖并排比看","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你把两帖并排，生辰相对，像两人隔纸相见。绣儿说这叫天作，你嗔她嘴巧。","source":"《仪礼·士昏礼》。"},{"text":"只记他生辰不问别的","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你只牢生辰，绣儿笑你偏心。你分辩：记生辰才好备礼嘛。嘴却先软了。","source":"同上。"}],"difficulty":2,"npc":["张媒婆","爹"],"foreshadow":"庚帖"},{"id":"F-011-未","branch":"F","stage":2,"day":11,"shichen":"未时","checkpoint":"字的解读","scene":"绣儿说「明远」取「明德致远」之意，是顾家祖父所起。你咂摸，这字果然配那清癯疏朗的人。","options":[{"text":"把「明远」念给娘听","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你念给娘听，娘赞好字。你心里：人如其字，字如其人，越想越妥。","source":"《礼记》。"},{"text":"疑字是后来改的","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你疑是及第后改字，绣儿笑：幼时起的好不？你讪讪，倒更信他家学。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"顾景行的字"},{"id":"F-011-戌","branch":"F","stage":2,"day":11,"shichen":"戌时","checkpoint":"供庚帖","scene":"戌时娘说问名既成，下步纳吉卜卦。你摸着庚帖，想那「明远」二字，竟比真人也先住了进你心里。","options":[{"text":"把庚帖供在案上","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你将庚帖端供案头，像供一桩心事。娘进来添灯，看你出神，轻轻带上门。","source":"《梦粱录·嫁娶》。"},{"text":"问娘纳吉可免","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你问卜卦能否省，娘正色：吉凶要问天意。你点头，倒敬这郑重。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"庚帖"},{"id":"F-012","branch":"F","stage":2,"day":12,"shichen":"辰时","checkpoint":"纳吉卜卦","scene":"爹请卜者灼龟问吉，卦象大吉。娘喜道：这便该用泥金帖子往顾家报喜了。你听「泥金」二字，觉富贵又妥帖。","options":[{"text":"盼那泥金帖子早成","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你想着泥金帖该多亮，像这桩喜事也镀了金。绣儿说姑娘眼里有光，你忙低头。","source":"《梦粱录·嫁娶》。"},{"text":"疑卜卦不准","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你小声疑卜者糊弄，爹瞪：童言无忌！你吐舌，心里却也盼大吉是真。","source":"同上。"}],"difficulty":2,"npc":["爹","娘"],"foreshadow":"泥金帖子"},{"id":"F-012-未","branch":"F","stage":2,"day":12,"shichen":"未时","checkpoint":"卜兆","scene":"娘说纳吉之兆主「宜室宜家」，与庚帖合婚正应。你本半信，听这四字，竟生出水到渠成的安然。","options":[{"text":"把「宜室宜家」记在笺上","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你提笔抄下四字，压在镜台。每日对镜，便似见一句好话等着你。","source":"《诗经》。"},{"text":"笑娘又引经","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你笑娘掉书袋，娘拧你：这是为你高兴！你忙撒娇，心里甜丝丝的。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"泥金帖子"},{"id":"F-012-戌","branch":"F","stage":2,"day":12,"shichen":"戌时","checkpoint":"金粉微闪","scene":"戌时绣儿捧来泥金帖子样张，金粉在灯下微闪。你俩凑近看，她悄说：这帖子一去，姑娘便是顾家准媳妇了。你拧她，手却抖。","options":[{"text":"抚那金粉轻声认了","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你抚那金粉，轻声说准便准罢。绣儿笑你认了，你埋进被里，心跳如鼓。","source":"《梦粱录·嫁娶》。"},{"text":"说帖子是爹娘做主","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"你说帖子是爹娘做主，自己只管欢喜。绣儿叹你嘴硬心软，你由她叹去。","source":"同上。"}],"difficulty":2,"npc":["绣儿"],"foreshadow":"泥金帖子","flavor":true},{"id":"F-013","branch":"F","stage":2,"day":13,"shichen":"辰时","checkpoint":"泥金报喜","scene":"辰时媒人执泥金帖子往顾家纳吉报喜，顾家受帖，回礼是四色果与一封谢函。喜气这回坐实了，满院都笑。","options":[{"text":"隔帘看那泥金帖出门","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你望那金帖被捧出门，像喜讯长了翅。绣儿说姑娘笑出酒窝，你忙捂脸。","source":"《梦粱录·嫁娶》。"},{"text":"只问回礼厚薄","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你问回礼多少，爹笑你俗。你分辩：问问不成？心里却早被喜填满。","source":"同上。"}],"difficulty":2,"npc":["张媒婆","爹"],"foreshadow":"泥金帖子"},{"id":"F-013-未","branch":"F","stage":2,"day":13,"shichen":"未时","checkpoint":"诗笺回赠","scene":"媒婆带回一封诗笺——竟是顾景行亲笔，谢程家错爱，附小诗一首，末句「遥寄海棠，静待清风」。你握笺的手微微发颤。","options":[{"text":"一字一句读那诗笺","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你反复读那「静待清风」，像听他在耳边说话。绣儿说姑娘哭了，你才知眼角湿了。","source":"宋代笔记。"},{"text":"只赏字不读诗","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你只夸他字好，绣儿急：快读诗呀！你忙念，读罢才觉心跳漏了半拍。","source":"同上。"}],"difficulty":2,"npc":["张媒婆"],"foreshadow":"诗笺"},{"id":"F-013-戌","branch":"F","stage":2,"day":13,"shichen":"戌时","checkpoint":"对灯展笺","scene":"戌时你展诗笺对灯，墨迹温润，「海棠」分明指你。你忽觉这未谋面的人，已隔着纸，轻轻握了你的手。","options":[{"text":"把诗笺系在香囊上","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你将诗笺一角系上并蒂莲香囊，像把他的话别在身边。夜风过，你第一次安睡。","source":"宋代笔记。"},{"text":"怕绣儿笑藏得太明显","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你想藏深些怕人笑，绣儿却道：该让人知道姑娘欢喜。你一想，倒坦然了。","source":"同上。"}],"difficulty":2,"npc":["绣儿"],"foreshadow":"诗笺"},{"id":"F-014","branch":"F","stage":2,"day":14,"shichen":"辰时","checkpoint":"诗笺回味","scene":"绣儿说顾景行那诗在士林传看，都赞「情深而不佻」。你听「不佻」二字，知他守礼，更敬他三分。","options":[{"text":"把「不佻」二字也记下","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你另抄「不佻」二字，与他字并排。绣儿说姑娘这账记得细，你笑：是心细。","source":"宋代笔记。"},{"text":"疑诗是幕僚代写","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你疑诗非亲笔，绣儿笑：字与庚帖一般无二哩。你一想，脸先热了。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"诗笺"},{"id":"F-014-未","branch":"F","stage":2,"day":14,"shichen":"未时","checkpoint":"纳征议","scene":"爹娘议纳征：男方聘礼单将到，娘主张嫁妆要厚，聘礼全收再添奁，不教女儿在顾家短了份。","options":[{"text":"赞娘的主意周全","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你赞娘想得远，娘说：不是争气，是护你。你鼻头一酸，原来都被疼着。","source":"《梦粱录·嫁娶》。"},{"text":"劝省些聘礼","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你劝别太铺张，爹笑：傻闺女，这是体面。你嘟嘴，却信爹娘的算盘。","source":"同上。"}],"difficulty":2,"npc":["爹","娘"],"foreshadow":"聘礼单"},{"id":"F-014-戌","branch":"F","stage":2,"day":14,"shichen":"戌时","checkpoint":"摊嫁妆簿","scene":"戌时娘摊开嫁妆簿，一项项念给你听。你本嫌烦，听娘说「这都是你的底气」，忽觉出嫁也不是抽身。","options":[{"text":"帮娘在簿上添一物","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你提笔在簿尾添了并蒂莲香囊，娘笑：这算什么礼。你道：算我的心意。","source":"同上。"},{"text":"问娘添多了顾家嫌","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你忧添多惹嫌，娘笑：厚奁是程家脸面，他家懂的。你安心，倒盼单子早到。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"聘礼单"},{"id":"F-015","branch":"F","stage":2,"day":15,"shichen":"辰时","checkpoint":"聘礼单到","scene":"辰时顾家递来聘礼单：羊酒、绸缎、珠翠、礼书。爹捋须：虽清寒，样样齐整，是个人家气派。","options":[{"text":"逐样看那聘礼单","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你细看每项，像摸他家诚心。绣儿说姑娘比账房还细，你啐她，手里却不停。","source":"《梦粱录·嫁娶》。"},{"text":"嫌礼轻","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你嘀咕礼薄，爹正色：清寒之家倾其所有，你看轻了人心。你忙改口，脸红。","source":"同上。"}],"difficulty":2,"npc":["张媒婆","爹"],"foreshadow":"聘礼单"},{"id":"F-015-未","branch":"F","stage":2,"day":15,"shichen":"未时","checkpoint":"当裘备礼","scene":"绣儿说顾景行为备聘礼，当了旧裘。你听罢心口一紧：这人宁可自己寒，也不教程家失了礼数。","options":[{"text":"把诗笺又展读一遍","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你重读「静待清风」，越读越暖。绣儿说姑娘这是心疼了，你默认，不辩。","source":"宋代笔记。"},{"text":"疑当裘是穷酸","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你脱口嫌穷酸，绣儿急：那是骨气！你一想，羞得埋进枕里。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"诗笺"},{"id":"F-015-戌","branch":"F","stage":2,"day":15,"shichen":"戌时","checkpoint":"全收添奁","scene":"戌时娘说聘礼全收，再添田庄铺面作奁。你摸着礼书，想那头的人，正为他家清寒不好意思哩。","options":[{"text":"盼他莫为礼薄不安","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你低声：他莫要不安才好。娘笑：你倒替他想。你这才觉，自己早已偏向他。","source":"《梦粱录·嫁娶》。"},{"text":"问娘添奁可压他一头","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你忧添多压人，娘笑：是体面不是压。你点头，倒更敬那当裘的人。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"聘礼单"},{"id":"F-016","branch":"F","stage":2,"day":16,"shichen":"辰时","checkpoint":"添奁","scene":"爹娘定下添奁：两顷田、一间绸庄、四季衣裳百箱。爹肉痛却硬气：我闺女，风光嫁过去！","options":[{"text":"谢爹娘这份底气","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你福身谢爹娘，爹别过脸抹眼。你知这底气，是全家替你攒的。","source":"《梦粱录·嫁娶》。"},{"text":"劝爹留些银钱","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你劝爹留本钱，爹笑：闺女比我会过。你却知，他是真舍得。","source":"同上。"}],"difficulty":2,"npc":["娘","爹"],"foreshadow":"聘礼单"},{"id":"F-016-未","branch":"F","stage":2,"day":16,"shichen":"未时","checkpoint":"香囊定奁","scene":"绣儿把并蒂莲香囊正式收进奁匣，说这是姑娘亲手，最金贵。你看着它躺在锦中，像自己先到了那头。","options":[{"text":"把香囊摆在奁顶","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你将香囊置于奁顶，像给自己留个记号。绣儿说这香囊，比珠翠还亮。","source":"同上。"},{"text":"又补几针怕不够好","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你总嫌针脚丑想重绣，绣儿拦：原样才好。你停手，倒觉真实可贵。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"并蒂莲香囊"},{"id":"F-016-戌","branch":"F","stage":2,"day":16,"shichen":"戌时","checkpoint":"先到顾家","scene":"戌时你俩理奁，绣儿忽然正经：姑娘，这香囊随你过去，便算姑娘先到了顾家。你愣，旋即笑，灯下把香囊贴了贴心口。","options":[{"text":"把香囊贴胸说那便先去","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你把香囊贴胸，轻声说：那便先去也好。绣儿眼眶红，你笑她多情。","source":"《礼记》。"},{"text":"说奁中唯这物自己做主","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"你说奁中唯这物是自己做主，绣儿笑：姑娘早把心许了。你由她，不辩。","source":"同上。"}],"difficulty":2,"npc":["绣儿"],"foreshadow":"并蒂莲香囊","flavor":true},{"id":"F-017","branch":"F","stage":2,"day":17,"shichen":"辰时","checkpoint":"纳征礼成","scene":"媒婆来说纳征礼成，两下交换礼书，亲事算定了大半。爹长舒：这回，任谁也抢不走我女婿了。","options":[{"text":"悄悄松了口气","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你听见「定了」，肩头一松。绣儿笑你装淡定，你由她，心里早开了花。","source":"《梦粱录·嫁娶》。"},{"text":"问还有哪家抢过","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你好奇谁还抢过，绣儿数落你后知后觉。你讪讪，倒庆幸爹手脚快。","source":"同上。"}],"difficulty":2,"npc":["爹","张媒婆"],"foreshadow":"聘礼单"},{"id":"F-017-未","branch":"F","stage":2,"day":17,"shichen":"未时","checkpoint":"期程","scene":"娘说亲迎尚早，须等顾景行除服赴任，才好办。你摸诗笺，想那「静待清风」，原是两人都要等。","options":[{"text":"把等待也当安稳","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你想通了：等，也是喜的一部分。绣儿说姑娘懂事了，你笑：是被人教会了。","source":"宋代笔记。"},{"text":"怨等得太久","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你嫌等得磨人，娘笑：好饭不怕晚。你哼唧，却也知急不得。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"诗笺"},{"id":"F-017-戌","branch":"F","stage":2,"day":17,"shichen":"戌时","checkpoint":"对月念诗","scene":"戌时你展诗笺对月，想那头的人也该在读你的庚帖。汴河灯如旧，你却觉灯里多了一个人的影。","options":[{"text":"把诗笺对月念一遍","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你低声念诗，月色似应。绣儿说姑娘念给月亮听，你笑：月亮最守秘。","source":"同上。"},{"text":"问绣儿可替我寄回诗","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你想回诗又怕失范，绣儿劝：礼未到不可私相授受。你醒神，只把话咽下。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"诗笺"},{"id":"F-018","branch":"F","stage":2,"day":18,"shichen":"辰时","checkpoint":"铺面交代","scene":"爹拉你到绸庄，说这添作奁产，日后归你自理。你头回觉出嫁不是去旁人家，是带了自家天地过去。","options":[{"text":"把绸庄名记在心上","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你默念庄名，像念一处新家。爹笑闺女开窍了，你由他夸。","source":"《梦粱录·嫁娶》。"},{"text":"推说不会打理","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你怕不会理账，爹笑：有娘教你。你安心，倒盼早些上手。","source":"同上。"}],"difficulty":1,"npc":["爹"],"foreshadow":"聘礼单"},{"id":"F-018-未","branch":"F","stage":2,"day":18,"shichen":"未时","checkpoint":"香囊再缝","scene":"绣儿说香囊里该添些香料，塞了苏合。你缝时扎了手，血珠染红并蒂莲，你倒觉得，这红更像喜气。","options":[{"text":"把染红处绣成花蕊","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你顺势绣朵红蕊，香囊更好看了。绣儿说姑娘手巧心也巧，你笑：是喜气巧。","source":"同上。"},{"text":"恼自己笨手","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你恼扎了手，绣儿笑笨人有笨福。你啐她，却把香囊收得更紧。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"并蒂莲香囊"},{"id":"F-018-戌","branch":"F","stage":2,"day":18,"shichen":"戌时","checkpoint":"娘来厢房","scene":"戌时娘看你缝香囊，忽然说：等你过去，这香囊便替娘陪着你。你鼻酸，知这针线里，缝着两代人的心意。","options":[{"text":"把香囊系在娘手上试","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你为娘系上香囊，娘笑出了泪。你知，这香囊迟早两头都暖。","source":"同上。"},{"text":"问娘舍不得怎办","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你忧娘不舍，娘笑：闺女大了，该去享福。你埋进娘怀里，不言语。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"并蒂莲香囊"},{"id":"F-019","branch":"F","stage":2,"day":19,"shichen":"辰时","checkpoint":"期请","scene":"媒婆来说顾景行已领官缺，亲迎之期可拟于秋后。爹拍板：好！趁着菊花开，热热闹闹娶我闺女。","options":[{"text":"暗喜秋后便能见他","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你想秋后便能真见那人，心跳快了。绣儿说姑娘终于盼到头，你笑不掩喜。","source":"《梦粱录·嫁娶》。"},{"text":"嫌秋后太远","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你怨秋后远，爹笑：急什么，好日子跑不了。你哼唧，却也认了。","source":"同上。"}],"difficulty":2,"npc":["张媒婆","爹"],"foreshadow":"聘礼单"},{"id":"F-019-未","branch":"F","stage":2,"day":19,"shichen":"未时","checkpoint":"诗笺珍藏","scene":"绣儿帮你把诗笺郑重收进奁顶锦匣，说这是姑爷头一份心意，得供着。你抚匣，像抚一段未见的缘分。","options":[{"text":"把诗笺当作定情物","correct":true,"tags":["情缘","感情"],"dims":{"情缘":2},"feedback":"你认下这诗笺是定情，绣儿笑你早该认。你红脸，却把匣子锁得妥帖。","source":"宋代笔记。"},{"text":"只当寻常书信","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"你嘴硬说只是书信，绣儿笑：姑娘自欺呢。你由她笑，心里早认了。","source":"同上。"}],"difficulty":2,"npc":["绣儿"],"foreshadow":"诗笺"},{"id":"F-019-戌","branch":"F","stage":2,"day":19,"shichen":"戌时","checkpoint":"描海棠","scene":"戌时娘说亲事定矣，余下只待迎。你望着诗笺上「海棠」，想那头的人，也该在灯下想着这边的你。","options":[{"text":"把「海棠」二字描进帕","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你挑灯在帕角描下海棠，像回他一句。娘见只笑，不说破。","source":"同上。"},{"text":"问娘他可会嫌我","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你忽然没自信，娘笑：他谢帖诗都写了，还嫌？你安心，倒怪自己多心。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"诗笺"},{"id":"F-020","branch":"F","stage":2,"day":20,"shichen":"辰时","checkpoint":"待迎","scene":"爹娘最后核奁单，样样齐备。爹叹：我程家闺女，风风光光。你站在一旁，忽觉自己像件被全家捧着的宝贝。","options":[{"text":"谢爹娘把自己当宝贝","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你福身谢爹娘，爹娘都笑出了泪。你知，这宝贝是人疼出来的。","source":"《梦粱录·嫁娶》。"},{"text":"嫌爹娘太铺张","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你嫌排场大，爹笑：一辈子一回，值！你嘟嘴，却暖在心里。","source":"同上。"}],"difficulty":2,"npc":["爹","娘"],"foreshadow":"聘礼单"},{"id":"F-020-未","branch":"F","stage":2,"day":20,"shichen":"未时","checkpoint":"香囊终奁","scene":"绣儿将并蒂莲香囊最终封入奁顶，说此物随姑娘过门，便是程顾两家并蒂。你摸着匣，像摸着自己的前半生。","options":[{"text":"把香囊再嗅一口苏合香","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你嗅那苏合，香气里全是喜。绣儿说姑娘这是舍不得，你笑：是带着走。","source":"同上。"},{"text":"又想拆开重缝","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你总想拆了重绣，绣儿拦：成了就成。你停手，知有些事不必求全。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"并蒂莲香囊"},{"id":"F-020-戌","branch":"F","stage":2,"day":20,"shichen":"戌时","checkpoint":"一夜安稳","scene":"戌时娘与绣儿都来厢房，灯下你展诗笺与香囊并放。娘说：痴丫头，秋后便能真见他了。你笑，把两件宝贝拢进怀里。","options":[{"text":"把诗笺香囊都搂住","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你将诗笺香囊都搂住，轻声：那便等等也无妨。娘绣儿都笑，灯花结了一朵。","source":"《礼记》。"},{"text":"说往后奁中事自己作主","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"你说往后奁中事自己作主，娘笑：早该如此。你知这主见，是向着顾家那人。","source":"同上。"}],"difficulty":2,"npc":["绣儿","娘"],"foreshadow":"并蒂莲香囊","flavor":true},{"id":"F-021","branch":"F","stage":2,"day":21,"shichen":"辰时","checkpoint":"纳征","scene":"顾家老仆挑着雁币与泥金帖子进门，聘礼单子铺在案上。爹捋须道：「阿盈，这礼数，咱们得全收，再添一份厚奁回去。」你低头看那单子，墨迹未干。","options":[{"text":"静立一旁，听爹与老仆清点聘礼，把单子细细记下一笔","correct":true,"tags":["家世"],"dims":{"家世":2},"feedback":"你垂眸记礼，程家体面全在分寸里。爹颔首：『我女懂事。』这份周全，日后顾家都看在眼里。","source":"宋代纳征之礼，见《梦粱录·嫁娶》。"},{"text":"嫌礼单烦琐，推说由爹做主便好，转身去逗绣儿","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你抽身去，爹叹口气替你收了尾。虽是女儿家娇惯，却少了份过门前的周全。","source":"同上。"}],"difficulty":1,"npc":["爹","顾家老仆"],"foreshadow":"聘礼单子"},{"id":"F-021-未","branch":"F","stage":2,"day":21,"shichen":"未时","checkpoint":"纳征","scene":"娘展开那对雁币，轻声道：「这雁，一生只一侣。阿盈，过门后莫要任性。」你摸着雁身温润的木纹，想起昨夜灯下她替你绾发的手。","options":[{"text":"接过雁币，轻声应『娘放心，盈儿记着』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你指尖触到雁翼，也触到娘未说尽的牵挂。这份体贴，比百两聘礼更沉，顾郎日后也识得。","source":"纳征用雁，取守信之义，见《仪礼·士昏礼》。"},{"text":"笑说『一只木雁罢了，娘太郑重』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"娘怔了怔，将雁币搁回匣中。你无心一句话，倒把她的叮咛轻轻揭过了。","source":"同上。"}],"difficulty":1,"npc":["娘","绣儿"],"foreshadow":"雁币"},{"id":"F-021-戌","branch":"F","stage":2,"day":21,"shichen":"戌时","checkpoint":"纳征","scene":"戌时灯下，绣儿捧着添奁的清单来念，念到一双并蒂莲荷包时咯咯笑：「这可是小姐自己绣的，顾官人可知小姐手巧？」你抿嘴不答。","options":[{"text":"由她笑去，只说『荷包是娘教的针法』","correct":true,"tags":["感情","自主"],"dims":{"自主":1},"feedback":"你由着绣儿打趣，灯花轻爆。少女家的心事不必说破，这并蒂的针脚，自会替你到了顾家。","source":"宋俗奁具多女方手作，见《东京梦华录·娶妇》。"},{"text":"低声问绣儿『顾官人……可好脾性』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":1},"feedback":"绣儿压低嗓子学你：「听说顾官人温润，从不红脸。」你耳根一热，却把荷包收得更紧了。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"聘礼单子","flavor":true},{"id":"F-022","branch":"F","stage":2,"day":22,"shichen":"辰时","checkpoint":"纳征","scene":"张媒婆登门，递上顾家回的泥金帖子：「顾夫人说，礼全收了，添奁的厚意也心领。程员外，这亲事，板上钉钉咯。」爹大笑拍案。","options":[{"text":"含笑向张媒婆福一福：『劳烦婆婆奔走』","correct":true,"tags":["家世","名声"],"dims":{"名声":1,"家世":1},"feedback":"你礼数周全，张媒婆回去尽是好话。程顾两家的体面，原就在这一揖一笑里攒下。","source":"宋婚书用泥金帖，见《东京梦华录·娶妇》。"},{"text":"撇嘴道『她家穷进士，也配这般端着』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"张媒婆讪讪，爹瞪你一眼。一句话泄了轻狂，倒叫顾家面上不好看。","source":"同上。"}],"difficulty":1,"npc":["爹","张媒婆"],"foreshadow":"泥金帖子"},{"id":"F-022-未","branch":"F","stage":2,"day":22,"shichen":"未时","checkpoint":"纳征","scene":"娘拉你到镜前，比着那支顾家聘来的金步摇：「礼是重了，可盈儿，金玉是外头看的。你自个儿心里那杆秤，才最要紧。」你望着镜中人。","options":[{"text":"点头：『盈儿明白，秤在心里』","correct":true,"tags":["感情","自主"],"dims":{"自主":1,"情缘":1},"feedback":"你应得轻，却稳。娘放心一笑。盲婚哑嫁的年头，肯自己掂量轻重，已是难得的清醒。","source":"宋人重聘亦重门风，见《梦粱录·嫁娶》。"},{"text":"只盯着步摇欢喜：『这样沉，够风光了』","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你贪看金光，娘轻叹。风光是风光，可秤若只称外头，过门后难免被分量压着走。","source":"同上。"}],"difficulty":1,"npc":["娘","绣儿"],"foreshadow":"聘礼单子"},{"id":"F-022-戌","branch":"F","stage":2,"day":22,"shichen":"戌时","checkpoint":"纳征","scene":"你独坐，把玩那对木雁，忽然想：他放榜那日，可是真孤身一人？绣儿端汤来，见你出神，嘻嘻道：「小姐想姑爷啦？」你忙把雁藏进袖里。","options":[{"text":"淡淡道『只是想想这雁，一生一只』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你把雁贴着心口，第一次肯承认，也有几分盼着。这份念想，藏在木纹里，谁也瞧不见。","source":"雁取其不再偶，见《仪礼·士昏礼》。"},{"text":"恼道『胡说，谁想他』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你口不对心，耳根却红透。绣儿偷笑跑开，只留你与那对雁，在灯下对坐。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"雁币"},{"id":"F-023","branch":"F","stage":2,"day":23,"shichen":"辰时","checkpoint":"请期","scene":"顾家老仆送来择好的吉日单：三日后便要亲迎，说顾家清简，不愿劳师动众。爹皱眉：『三日？这排场如何来得及！』你在一旁听着。","options":[{"text":"轻声劝爹『顾家俭朴是读书人本分，风光不在日子急』","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"你一句话解了围。爹叹服：『我女竟比我想得透。』顾家俭朴，原是进士的清骨，值得敬。","source":"请期用雁，择吉日，见《仪礼·士昏礼》。"},{"text":"也催爹『快些张罗，莫叫顾家小瞧了』","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"爹被你一激，更要大办。可顾家本心俭朴，强撑排场，反显得两家门风不合。","source":"同上。"}],"difficulty":1,"npc":["爹","顾家老仆"],"foreshadow":"庚帖"},{"id":"F-023-未","branch":"F","stage":2,"day":23,"shichen":"未时","checkpoint":"请期","scene":"张媒婆来回说合：『顾夫人意思，亲迎从简，莫误姑爷观政。程员外若体面，添些自家排场无妨，只是莫累着新人。』你听得分明。","options":[{"text":"应道『从简也好，顾郎安心仕途要紧』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你替他想着仕途，张媒婆直夸贤惠。日后顾郎得知，必记你这一分体恤。","source":"宋进士授官须赴阙观政，见《宋史·选举志》。"},{"text":"嘟囔『从简，岂不叫姐妹们笑我寒伧』","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你只顾脸面，张媒婆噎住。风光是给别人看的，可新郎的仕途与心意，才是自家的。","source":"同上。"}],"difficulty":1,"npc":["张媒婆"],"foreshadow":"泥金帖子"},{"id":"F-023-戌","branch":"F","stage":2,"day":23,"shichen":"戌时","checkpoint":"请期","scene":"娘在灯下把吉日单压在妆奁下，忽然落泪：『三日后，我的盈儿就不再是程家的人了。』你握住她的手，那单子上墨字还新。","options":[{"text":"靠在娘肩头：『盈儿永远是娘的盈儿』","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"你一句话，娘破涕为笑。出嫁不是断线的筝，这门亲里，最稳的那根线，是娘给的。","source":"宋嫁女有『哭嫁』之俗，见《东京梦华录·娶妇》。"},{"text":"慌得只会说『娘莫哭，我不嫁了』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你口不择言，娘反倒笑了：『傻丫头，吉期已定，哪有不嫁的理。』","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"庚帖"},{"id":"F-024","branch":"F","stage":2,"day":24,"shichen":"辰时","checkpoint":"亲迎前夜","scene":"嫁妆发肆，箱笼排了一院。绣儿念着妆奁单：『这添的二十抬，是员外特意添的体面。』爹叮嘱：『莫教顾家觉着程家轻慢。』你看着满地红。","options":[{"text":"一一核对妆奁单，把陪嫁书目也添进去","correct":true,"tags":["家世","才华"],"dims":{"家世":1,"才华":1},"feedback":"你连陪嫁的书都列上，爹意外又欢喜。读书人的亲事，书比绫罗更见门风。","source":"宋嫁妆称『妆奁』，见《梦粱录·嫁娶》。"},{"text":"嫌琐碎：『横竖抬过去便是，单子何须我管』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你懒得理单，爹替你收尾。陪嫁是程家的脸，也是你的底，含糊不得。","source":"同上。"}],"difficulty":1,"npc":["爹","绣儿"],"foreshadow":"嫁妆单"},{"id":"F-024-未","branch":"F","stage":2,"day":24,"shichen":"未时","checkpoint":"亲迎前夜","scene":"张媒婆笑：『明儿姑爷来亲迎，得先作催妆诗，作不出，这青庐门可进不来。程家小姐，且等着听好诗罢。』你低头，袖中却扇微凉。","options":[{"text":"浅笑：『诗好不好，且听明日的』","correct":true,"tags":["感情","才华"],"dims":{"才华":1,"情缘":1},"feedback":"你不慌不骄，张媒婆乐了。催妆诗是文人的体面，你肯等，便是给顾郎留了面子。","source":"催妆诗之俗，见《东京梦华录·娶妇》。"},{"text":"抢白『他若作不出，便莫进门』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你嘴快，张媒婆讪讪。真要作不出，丢的是两家的脸，岂是赌气的事。","source":"同上。"}],"difficulty":1,"npc":["张媒婆"],"foreshadow":"催妆诗"},{"id":"F-024-戌","branch":"F","stage":2,"day":24,"shichen":"戌时","checkpoint":"亲迎前夜","scene":"夜深，娘把一面却扇交你：『明儿拜堂，拿它遮面。等他作却扇诗，你才肯移开——这是规矩，也是女儿家的分寸。』你抚过扇上并蒂莲。","options":[{"text":"接扇，轻声『盈儿记着，也记着娘』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"扇柄还留着娘掌心的暖。这把扇，遮的是面，护的是你初见夫家的羞与稳。","source":"却扇之礼，见唐五代婚俗，宋沿之。"},{"text":"赌气『凭什么我要躲着他』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你孩子气，娘摇头。却扇不是躲，是礼数里那一寸恰好的距离，急不得。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"却扇"},{"id":"F-025","branch":"F","stage":3,"day":25,"shichen":"辰时","checkpoint":"催妆诗","scene":"亲迎日，顾景行青衫玉带立门外，被拦着要催妆诗。你隔窗听他朗声吟：『妆台初月照新梅——』外头哄笑：『才一句，姑爷且想！』你咬住唇。","options":[{"text":"隔着窗，悄悄把第二句写在笺上递给绣儿转去","correct":true,"tags":["感情","才华"],"dims":{"才华":1,"情缘":1},"feedback":"你递的『莫道春寒锁旧闺』解了围。他接笺时指尖一颤——你虽不能见，却知他懂。","source":"催妆诗须即席，见《东京梦华录·娶妇》。"},{"text":"由他窘着，心想『才子也这般笨』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你坐着不动，外头笑成一团。他是真窘，你却错过头一回替他解围的亲近。","source":"同上。"}],"difficulty":2,"npc":["顾景行","张媒婆"],"foreshadow":"催妆诗"},{"id":"F-025-未","branch":"F","stage":3,"day":25,"shichen":"未时","checkpoint":"催妆诗","scene":"诗成了，门开。你被扶上花轿，抬进顾家青庐。他在外头整衣，你在帐内，嗅到新铺蒿草的清苦气，听见他脚步轻轻绕到门口。","options":[{"text":"静坐帐中，听他向傧相郑重道谢","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你不出声，却把他的郑重听进心里。青庐虽简，他待你，从第一刻便认真。","source":"亲迎设青庐，见《酉阳杂俎》及宋婚仪。"},{"text":"忍不住掀帘偷看，被绣儿按住","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你心急，绣儿笑拦。青庐里的新妇哪有先露面的理，这份莽撞，倒添了羞。","source":"同上。"}],"difficulty":2,"npc":["顾景行","顾家老仆"],"foreshadow":"青庐"},{"id":"F-025-戌","branch":"F","stage":3,"day":25,"shichen":"戌时","checkpoint":"催妆诗","scene":"戌时，青庐外灯火摇。绣儿凑你耳边：『姑爷方才还问，小姐可还紧张。我说小姐稳得很。』你握着却扇，扇骨硌着掌心。","options":[{"text":"低声『替我谢他，说我不怕』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"绣儿去传话，你不知他听完如何。只知这一夜，却扇虽未移，两颗心已先近了寸许。","source":"宋婚仪新妇持扇，见《东京梦华录·娶妇》。"},{"text":"叫绣儿『莫管，我自个儿静着』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你赶绣儿走，错过一回传话的近。新婚第一夜的体贴，原就在肯不肯开口。","source":"同上。"}],"difficulty":2,"npc":["绣儿"],"foreshadow":"却扇"},{"id":"F-026","branch":"F","stage":3,"day":26,"shichen":"辰时","checkpoint":"障车","scene":"却扇前还有一关：程家儿郎障车拦门，讨喜钱才放新人下轿。顾景行笑着解荷包：『诸位贤舅，景行这点俸外之资，都孝敬了。』你听得门外笑闹。","options":[{"text":"在轿中浅笑，由家中兄弟热闹去","correct":true,"tags":["感情","家世"],"dims":{"家世":1,"情缘":1},"feedback":"你不拦不恼，娘家兄弟尽兴，顾郎也体面。障车是热闹，不是刁难，你心里有数。","source":"障车之俗，见《酉阳杂俎》及宋笔记。"},{"text":"急着叫兄弟『快放他进来，怪寒酸的』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你心软替他解围，倒扫了兄弟的兴。障车讨的是彩头，哪能真嫌寒酸。","source":"同上。"}],"difficulty":2,"npc":["顾景行","张媒婆"],"foreshadow":"障车"},{"id":"F-026-未","branch":"F","stage":3,"day":26,"shichen":"未时","checkpoint":"却扇","scene":"下轿入堂，你以却扇遮面立着。他执笔，朗声吟却扇诗：『初见盈盈扇底春，愿将心事付良人。』你第一次，这么近听见他的声音，清润如檐下泉。","options":[{"text":"指尖微动，将却扇稍稍移开半寸","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"扇移半寸，你偷觑见他含笑的眼。这一寸，是礼数，也是你肯递过去的第一分心意。","source":"却扇诗之俗，见唐五代及宋婚仪笔记。"},{"text":"死死捂着扇，一声不吭","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你绷着不松手，他诗虽好，却接不到你的回应。新婚头一面，便隔着一扇生分。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"却扇"},{"id":"F-026-戌","branch":"F","stage":3,"day":26,"shichen":"戌时","checkpoint":"却扇","scene":"戌时，傧相捧来合卺杯。绣儿低声：『姑爷说，杯是借的，顾家清简，用了便还。』你看着那对剖开的匏瓜，他端端正正立在你身侧。","options":[{"text":"伸手与他共执匏杯，饮下那口酒","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"匏苦酒甘，你与他交臂而饮。借的杯不要紧，这口同心酒，顾家还不起，也无需还。","source":"合卺用匏，见《仪礼·士昏礼》。"},{"text":"嫌杯旧，迟迟不肯接","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你蹙眉，他手一僵。清简是进士的家底，你嫌的哪是杯，是错看了他的诚心。","source":"同上。"}],"difficulty":2,"npc":["顾景行","绣儿"],"foreshadow":"合卺杯"},{"id":"F-027","branch":"F","stage":3,"day":27,"shichen":"辰时","checkpoint":"同牢合卺","scene":"同牢之礼，两人共案而食。他夹一箸你爱的炙肉放你碗里，自己却只吃青菜。你想起娘说『清官人家，桌上见真章』，悄悄把菜也拨些给他。","options":[{"text":"也夹一箸菜，轻轻放进他碗心","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你回敬的那一箸，他怔了怔，低头吃尽。同牢的饭，原是要两人都肯给对方留一口。","source":"同牢合卺，见《仪礼·士昏礼》。"},{"text":"只低头吃自己的，当作没看见","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你不动，他也不好再让。一桌饭吃得安静，却把方才那点近，又推回半尺。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"合卺杯"},{"id":"F-027-未","branch":"F","stage":3,"day":27,"shichen":"未时","checkpoint":"同牢合卺","scene":"礼成，绣儿捧来剪：『姑爷，小姐，该结发了。』他执起你一缕发，与你的一并绾紧，低声：『结发为夫妻，恩爱两不疑。』你耳尖发烫。","options":[{"text":"任他绾发，轻声接『盈儿记着这句』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你应了那句诗，他手指稳。结发不是形式，是两人都肯把这根线，系在对方命里。","source":"结发之仪，见《古诗·结发为夫妻》及宋俗。"},{"text":"羞得缩手，结发草草了事","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你一缩，发结歪了。绣儿偷偷扶正，你却错失了与他第一次，郑重交握的指温。","source":"同上。"}],"difficulty":3,"npc":["顾景行","绣儿"],"foreshadow":"结发"},{"id":"F-027-戌","branch":"F","stage":3,"day":27,"shichen":"戌时","checkpoint":"同牢合卺","scene":"夜深，青庐烛剩半支。他为你掩被角，忽然极轻一句：『今日累着你了。』你闭眼装睡，听见他在案边静坐片刻，才悄然去外间。","options":[{"text":"在被中弯了弯唇角，由他安置","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你装睡，却把那句轻语收进梦里。合卺之事且缓，这一夜的妥帖，已是最好的开头。","source":"宋婚仪尚礼，闺帷之事含蓄，见《朱子家礼》。"},{"text":"猛地睁眼，慌得坐起说『我不困』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你一惊坐起，两人都窘。新婚夜的局促，原不必慌，静着便好。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"合卺杯"},{"id":"F-028","branch":"F","stage":3,"day":28,"shichen":"辰时","checkpoint":"回门","scene":"三朝回门，你携顾景行归宁。爹打量女婿：『姑爷清瘦，可见官中清苦。』娘拉你手：『顾家可待你厚？』你瞥见他恭敬立在爹身侧。","options":[{"text":"含笑答娘『厚在心里，不在排场』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你一句替顾家圆了场。爹娘安心，他也松肩。回门这关，你替他撑住了体面。","source":"三朝回门，见《梦粱录·嫁娶》。"},{"text":"如实嘟囔『他家连果子都省着买』","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你无心一句话，爹皱眉。清简是实情，可当爹娘面说破，倒显得顾家亏了你。","source":"同上。"}],"difficulty":1,"npc":["爹","娘"],"foreshadow":"回门礼"},{"id":"F-028-未","branch":"F","stage":3,"day":28,"shichen":"未时","checkpoint":"回门","scene":"娘塞给你一包枣与栗，压低声：『早立子，是老理。可盈儿，身子自己珍重，莫急着应旁人。』你握着温热的布包，想起娘昨夜的泪。","options":[{"text":"把枣栗收好，贴身应『盈儿知道』","correct":true,"tags":["感情"],"dims":{"情缘":1},"feedback":"你把娘的体己收进怀里。她在意子嗣，更在意你。这份懂得，是盲婚里最暖的凭仗。","source":"宋娶妇有『早立子』之祝，见《东京梦华录·娶妇》。"},{"text":"嫌土气，随手搁在案上","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你漫不经心，娘讪讪。那包枣栗是她能想的最实在的护，你却当寻常。","source":"同上。"}],"difficulty":1,"npc":["娘","绣儿"],"foreshadow":"回门礼"},{"id":"F-028-戌","branch":"F","stage":3,"day":28,"shichen":"戌时","checkpoint":"回门","scene":"戌时归顾宅，他替你卸了钗环，忽然道：『今日你替我圆的话，景行记着。』你笑：『夫妻本该如此。』他怔了怔，也笑了。灯下两人都没再拘着。","options":[{"text":"说『你也不必总端着，我在呢』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":1},"feedback":"你一句话，他肩头塌下半分。新婚头几日最怕生分，你肯叫他松，他便敢做真自己。","source":"宋士大夫家室，尚相敬如宾亦重相知，见笔记。"},{"text":"递茶给他『累了一日，先润润』","correct":true,"tags":["感情","自主"],"dims":{"自主":1},"feedback":"你递茶的手很稳。盲婚哑嫁的开头，原是一盏一盏茶，把生疏泡软的。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"结发","flavor":true},{"id":"F-029","branch":"F","stage":3,"day":29,"shichen":"辰时","checkpoint":"新婚","scene":"晨起，你看见顾家厅堂简素：一张旧木案，两把竹椅，连屏风都是素绢。老仆歉道：『姑爷清官，家中实在简。』你想起程家的朱漆描金。","options":[{"text":"抚过旧木案：『这样干净，住着舒心』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你不嫌清贫，他远远看见，眼神软了。进士的穷是实，可你肯安之，他便有了家。","source":"宋清官家多简素，见《宋史》及笔记。"},{"text":"蹙眉：『这般寒素，怎过日子』","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你脱口嫌简，老仆低头。他是清官傲骨，你嫌的哪是案，是错看了他的志。","source":"同上。"}],"difficulty":1,"npc":["顾景行","顾家老仆"],"foreshadow":"旧木案"},{"id":"F-029-未","branch":"F","stage":3,"day":29,"shichen":"未时","checkpoint":"新婚","scene":"他捧来一卷《白氏长庆集》：『案头书少，这本你先翻。顾家虽简，书是不缺的。』你接书，指腹蹭到书页边缘的批注，字迹清秀。","options":[{"text":"翻到批注处，轻声赞『这处解得好』","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"你一眼看到他的批注，他意外又欢喜。书香是顾家最厚的陪嫁，你接住了。","source":"宋士人重藏书批读，见《梦溪笔谈》等笔记。"},{"text":"随手搁下：『我读不读，不打紧』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你轻放，他眼底的光黯了黯。书是他递来的手，你松了手，便差一步亲近。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"旧木案"},{"id":"F-029-戌","branch":"F","stage":3,"day":29,"shichen":"戌时","checkpoint":"新婚","scene":"戌时，绣儿替你铺被，嘀咕：『这宅子冷清，小姐夜里怕不怕？』你望见窗外月照旧案，忽然觉得，简素里也有安稳。你摇摇头。","options":[{"text":"说『不怕，这样的静，正好想事儿』","correct":true,"tags":["感情","自主"],"dims":{"自主":1,"情缘":1},"feedback":"你贪这点静。盲婚头几日最慌的是噪，你偏安于简，倒先稳住了自己。","source":"宋闺秀多喜静读，见《东京梦华录》。"},{"text":"叹『早知这般冷清，何必嫁』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你一句悔语，绣儿噤声。冷清是眼前，可人还在将熟，莫急着下定论。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"旧木案"},{"id":"F-030","branch":"F","stage":3,"day":30,"shichen":"辰时","checkpoint":"见婆母","scene":"顾夫人唤你奉茶，规矩极严：跪姿、奉盏、退步，一步不错才接。你手稳，茶不溢。她抬眼：『程家小姐，规矩倒是齐整。』你垂首。","options":[{"text":"恭恭敬敬『媳妇笨，还请母亲教』","correct":true,"tags":["家世","名声"],"dims":{"家世":1,"名声":1},"feedback":"你谦得巧，顾夫人嘴角松了松。清官家规矩多却不恶，你肯低，她便肯容。","source":"宋妇礼重媳奉茶，见《朱子家礼》。"},{"text":"挺直回『程家教得，不必再教』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你昂着回，顾夫人敛了笑。规矩人家最忌张扬，你这一句，倒显程家教得过了。","source":"同上。"}],"difficulty":2,"npc":["顾夫人","顾景行"],"foreshadow":"玉梳"},{"id":"F-030-未","branch":"F","stage":3,"day":30,"shichen":"未时","checkpoint":"见婆母","scene":"顾夫人取一支素玉梳给你：『我家清，给不了金玉。这梳是我陪嫁的，给你，盼你往后，把日子也梳得顺顺的。』你接梳，玉沁凉。","options":[{"text":"双手接过『媳妇定好好珍着』","correct":true,"tags":["感情","家世"],"dims":{"家世":1,"情缘":1},"feedback":"你接的是她陪嫁的旧物，也是一份托付。清官之家的情，原就这么素净实在。","source":"宋婆母赐物示接纳，见《梦粱录·嫁娶》。"},{"text":"嫌素，勉强收下不言语","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你嫌玉不华，神色漏了。她瞧在眼，不恼，却也把亲近收回了三分。","source":"同上。"}],"difficulty":1,"npc":["顾夫人"],"foreshadow":"玉梳"},{"id":"F-030-戌","branch":"F","stage":3,"day":30,"shichen":"戌时","checkpoint":"见婆母","scene":"戌时他来问：『母亲可难为你？』你摸出那支玉梳晃了晃：『难为倒没有，倒是得了把梳子。』他舒口气，笑：『我娘那人，心软嘴硬。』","options":[{"text":"笑应『我瞧出来了，随你』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你一句话，把他娘与他都认下了。婆媳的冰，原是女婿一句话，给你捂化的。","source":"宋婿为妻调停母家，见笔记。"},{"text":"冷道『你娘，是厉害些』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你一句生评，他尴尬。母亲再严也是他娘，你嫌，便把他夹在中间难做。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"玉梳"},{"id":"F-031","branch":"F","stage":3,"day":31,"shichen":"辰时","checkpoint":"书房","scene":"他引你入书房：『你若闷，可来此处翻书，只是莫乱我案上公文。』你点头，目光却落在书架底层一本旧书——那是你娘家也有的《女诫》注本。","options":[{"text":"只立门口看，轻声『我不打扰你』","correct":true,"tags":["感情","自主"],"dims":{"自主":1,"情缘":1},"feedback":"你知分寸，他安心。书房是他立身之地，你肯在门外守着，他便肯为你留门。","source":"宋士人重书房，见《梦溪笔谈》。"},{"text":"径直去翻他案上公文","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你手快碰了公文，他皱眉却没说。书房是他的禁地，你这一步，越了界。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"书"},{"id":"F-031-未","branch":"F","stage":3,"day":31,"shichen":"未时","checkpoint":"书房","scene":"两人各据一桌看书，静得只闻翻页。你想问他一句批注，开口又咽下。他似察觉，抬眼望你，四目一碰，你忙低头，耳热。","options":[{"text":"把想问的，写在笺上推过去","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"你以笺代口，他看完笑了。尴尬的静里，你先递出一根线，他便接得住。","source":"宋人书问多用便笺，见笔记。"},{"text":"硬憋着，一午后无话","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你憋住不问，一下午空过。书房初话最难得，你一退，便又生分半日。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"书"},{"id":"F-031-戌","branch":"F","stage":3,"day":31,"shichen":"戌时","checkpoint":"书房","scene":"戌时灯下，他忽道：『你方才那笺，问得巧。我少时读书，也卡在这一句。』你笑：『巧了，我也卡过。』两人都笑了，书还摊着，话却热了。","options":[{"text":"说『那咱们以后，卡着便互相问』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":1},"feedback":"你一句约，把书房变成两人的。盲婚哑嫁，最怕无话，你肯约，他便肯常陪。","source":"宋夫妻唱和多自书室始，见宋代笔记。"},{"text":"笑『原来你也不是凡事都懂』","correct":true,"tags":["感情","自主"],"dims":{"自主":1},"feedback":"你打趣他，他不恼反乐。能笑他的不是处，才是真走近了一步。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"书","flavor":true},{"id":"F-032","branch":"F","stage":3,"day":32,"shichen":"辰时","checkpoint":"书房","scene":"他似不经意：『听闻程家是商贾起家，你自幼，可读过些书？』你指尖一顿——你在娘家，原是偷着读过几本的。抬眼，对上他探究的目光。","options":[{"text":"坦然『偷读过些，怕爹说女孩家不必，便藏着』","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"你说实话，他眼睛亮了。他试探的从不是书，是你肯不肯对他交心。","source":"宋闺秀私读甚多，见《东京梦华录》。"},{"text":"慌答『不曾，女儿家读什么书』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你藏了底，他微微失望。本是投石问路，你缩回，他便以为你真无此好。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"你偷读的书"},{"id":"F-032-未","branch":"F","stage":3,"day":32,"shichen":"未时","checkpoint":"书房","scene":"他递来纸笔：『既读过，写几个字我瞧瞧。』你想起娘家灯下临的帖，落笔竟稳。他看罢，唇角弯起：『程家藏了个才女，倒瞒得紧。』","options":[{"text":"落笔写『盈盈一水间』，不解释","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"你写那句，他懂是《古诗》里望穿的意。这一手字，比千言先替你开了口。","source":"宋以字观人，见笔记。"},{"text":"推说『手生，写不好』不肯动笔","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你怯场不肯写，他也不强。可那扇门，你原可以推开的，偏又合上了。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"你偷读的书"},{"id":"F-032-戌","branch":"F","stage":3,"day":32,"shichen":"戌时","checkpoint":"书房","scene":"绣儿收拾纸笔，偷笑：『小姐方才那字，姑爷瞧了半晌不肯放。』你脸一热，把那张纸悄悄收进袖：『莫声张，叫人笑我卖弄。』","options":[{"text":"收好字纸，只淡淡『他爱看便看』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你藏起那纸，却藏不住喜。他爱看，你便值得写——这桩盲婚，渐渐有了光。","source":"宋夫妻以字传情，见宋代笔记。"},{"text":"抢过纸揉了『丢人现眼』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你一揉，绣儿愣住。那纸是他半日欢喜，你嫌羞，倒把刚起的暖揉没了。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"你偷读的书"},{"id":"F-033","branch":"F","stage":3,"day":33,"shichen":"辰时","checkpoint":"新婚","scene":"你忽问：『放榜那日，你同乡同年都在，怎的独你一个，被我爹捉了来？』他执杯的手顿了顿，笑：『许是景行，命里该落程家。』你觉出他避重就轻。","options":[{"text":"不追逼，只说『不愿说时，便不说』","correct":true,"tags":["感情","自主"],"dims":{"自主":1,"情缘":1},"feedback":"你给他退路，他松口气。试探的分寸，在肯停手——你停了，他日自会肯讲。","source":"宋人交际重分寸，见笔记。"},{"text":"追问『你是不是有什么瞒我』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你逼一句，他笑意淡了。新婚未稳便查底，倒显得信不过他。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"同乡帖"},{"id":"F-033-未","branch":"F","stage":3,"day":33,"shichen":"未时","checkpoint":"新婚","scene":"他沉默半晌，竟开了口：『同年都劝我攀权贵高门，我婉拒了。程家虽商，你爹待我以礼，你……我没见过，却信几分缘。』你没想到他说得这样直。","options":[{"text":"轻声『那你，可后悔拒了高门』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你这一问，是把真心递回去。他拒高门选你，你肯认，这段缘才立得稳。","source":"宋进士多择婿攀援，见《宋史·选举志》。"},{"text":"得意『那是，高门哪有程家好』","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你占了上风，他却不语。他拒高门是傲骨，不是比你家强，你一句得意，轻了他的志。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"同乡帖"},{"id":"F-033-戌","branch":"F","stage":3,"day":33,"shichen":"戌时","checkpoint":"新婚","scene":"戌时他取出一封同乡旧帖，搁在案上：『这是他们劝我的信。你若想看，便看。景行既入程门，这些，原不必瞒你。』你望着那封旧帖。","options":[{"text":"只拂过帖角，不拆『你的旧事，你肯说我才听』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你不拆他的旧，他反倒想全说。信任是这般——你给空间，他交 entirety。","source":"宋人重信义，见笔记。"},{"text":"立刻拆开细读『我瞧瞧他们说什么』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你动手拆，他略僵。旧帖是他的隐私，你急读，倒显得不肯等他开口。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"同乡帖"},{"id":"F-034","branch":"F","stage":3,"day":34,"shichen":"辰时","checkpoint":"新婚","scene":"他下值回来，袖中鼓鼓，忽然掏出一串红果：『街口新下的林檎，想起你爱吃酸的，便买了一串。』你盯着那串沾露的果子，愣住。","options":[{"text":"接过，咬一口酸得眯眼『甜的是你记着』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你一句，他耳根红了。进士的穷，买不起珍玩，可这串林檎，比金贵。","source":"宋市井果品见《东京梦华录·果子》。"},{"text":"嫌『一串野果，也值当』","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你嫌他礼轻，他讪讪收手。他记你口味的心，被你一句话，贬成了野果。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"果子"},{"id":"F-034-未","branch":"F","stage":3,"day":34,"shichen":"未时","checkpoint":"新婚","scene":"绣儿笑：『姑爷方才在街口挑了半晌，说要选最红的。摊主还笑他，新科进士穷讲究。』你捏着那串林檎，核都舍不得吐。","options":[{"text":"把一颗最红的塞绣儿『你也尝尝他的讲究』","correct":true,"tags":["感情","自主"],"dims":{"自主":1,"情缘":1},"feedback":"你分一颗给绣儿，也分一份欢喜。他穷讲究的体贴，你肯与人共，便更真了。","source":"宋市井细事，见《东京梦华录》。"},{"text":"只顾自己吃，由绣儿说去","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你独享不理，绣儿撇嘴。甜是两人事，你一人吃了，倒显得薄了那份心。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"果子"},{"id":"F-034-戌","branch":"F","stage":3,"day":34,"shichen":"戌时","checkpoint":"新婚","scene":"戌时你拈着最后一颗林檎，忽然问他：『你如何知我爱酸的？』他笑：『纳采那日，你爹说你少时偷啃青梅。』你愣：『你竟记得。』灯下两人都笑了。","options":[{"text":"说『那往后，酸的我留一半给你』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":1},"feedback":"你一句分果，他把你那点酸，都尝成甜。盲婚里的小事，原最养人。","source":"宋人夫妻以细物传情，见笔记。"},{"text":"笑『你记这些，倒比记公文清楚』","correct":true,"tags":["感情","自主"],"dims":{"自主":1},"feedback":"你打趣他好记性，他也不恼。能拿他打趣，是这段缘，开始松快的证据。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"果子","flavor":true},{"id":"F-035","branch":"F","stage":3,"day":35,"shichen":"辰时","checkpoint":"补官服","scene":"他上值前，你见官服袖口脱了线：『这衣该补了。』他不在意：『小事，穿着不妨。』你摸那磨白的袖缘，想起他清简的家底。","options":[{"text":"取针线『我替你缝，莫叫同僚瞧出寒酸』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你动手补，他怔住。进士的体面，你替他护着，这针脚里，是他读不懂的体贴。","source":"宋官服称『公服』，见《宋史·舆服志》。"},{"text":"由他去『破便破，横竖是官身』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你不管，他穿着破袖上值。你不在意，他却少了一份被惦记的暖。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"官服"},{"id":"F-035-未","branch":"F","stage":3,"day":35,"shichen":"未时","checkpoint":"补官服","scene":"绣儿递来同色丝线：『小姐这针法，是程家绣娘的手艺罢？』你低头缝合，针脚细密。想起娘说『补衣如补家，线要稳』。","options":[{"text":"稳稳缝完，在里子绣个小小『盈』字","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"你藏个私印在衣里，他日后方知。补的是衣，缝的是你愿陪他过清简的心。","source":"宋妇功尚刺绣，见《东京梦华录·嫁娶》。"},{"text":"粗粗缝几针敷衍了事","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你潦草收针，绣儿摇头。补衣是心意，你敷衍，便敷衍了这段刚起的温度。","source":"同上。"}],"difficulty":2,"npc":["绣儿"],"foreshadow":"官服"},{"id":"F-035-戌","branch":"F","stage":3,"day":35,"shichen":"戌时","checkpoint":"补官服","scene":"他归家，摸袖口愣了：『这针脚……是你的？』你佯装无事：『顺手罢了。』他低声：『景行记着这袖子，往后不舍得磨了。』你别过脸。","options":[{"text":"轻声『磨坏了，我再补』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你一句再补，他笑了。清简的日子，有你这句托底，他便敢穿旧也穿暖。","source":"宋夫妻相恤，见笔记。"},{"text":"冷道『一件破衣，值得这般』","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你故作冷淡，他讪讪。那袖子是他第一份被缝的暖，你一句，又推远了。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"官服"},{"id":"F-036","branch":"F","stage":3,"day":36,"shichen":"辰时","checkpoint":"新婚","scene":"一同年登门，寒暄后低声劝他：『景行，王相家尚有女未字，你若回心，未为晚。』你端茶立侧，听得真切，手稳，茶不洒。","options":[{"text":"不动声色退下，由他应付","correct":true,"tags":["家世","自主"],"dims":{"自主":1,"名声":1},"feedback":"你体面退开，给他留面。同年劝攀，他既拒过一次，你信他再拒，不必搅。","source":"宋同年相援引，见《宋史·选举志》。"},{"text":"当面冷笑『我程家，轮得到你嫌』","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你一句抢白，同年尴尬去。话是解气，却把他的难处，当众掀了开来。","source":"同上。"}],"difficulty":2,"npc":["顾景行","顾家老仆"],"foreshadow":"同乡帖"},{"id":"F-036-未","branch":"F","stage":3,"day":36,"shichen":"未时","checkpoint":"新婚","scene":"同年走后，他叹：『你都听见了。』你点头。他正色：『景行既入了程门，便是一生。高门权贵，诱得过，心过不得。』你望进他眼里。","options":[{"text":"柔声『我信你，方才才肯退下』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你一句信，他肩头松了。同年的话说破，反倒成你们之间的钉——把心钉得更牢。","source":"宋重信义婚盟，见《仪礼·士昏礼》。"},{"text":"淡淡『信不信，在你』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你淡淡的，他怔了怔。他既要你信，你偏不接，这段刚稳的缘，又悬起。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"同乡帖"},{"id":"F-036-戌","branch":"F","stage":3,"day":36,"shichen":"戌时","checkpoint":"新婚","scene":"戌时他取笔，在旧同乡帖后添一行：『程门顾景行，此生不二。』搁笔看你：『这帖，往后归你收着。』你望着那行字，墨迹未干。","options":[{"text":"接过帖子，压在妆奁最下『我替你存着』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你收下那行字，也收下他的誓。盲婚哑嫁里，这一帖，是两人肯交的底。","source":"宋人以帖为信，见笔记。"},{"text":"推回『你的字据，自个儿留』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你推回，他默默收起。他递的是心，你推的也是——这一推，凉了半寸。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"同乡帖"},{"id":"F-037","branch":"F","stage":3,"day":37,"shichen":"辰时","checkpoint":"补官服","scene":"他换下另一件公服，你见肘部也薄了：『怎的件件都磨肘。』他笑：『伏案多，难免。』你想起那袖里绣的『盈』字，唇角忍不住弯。","options":[{"text":"取衣『这件，我也替你补，里子再绣个花样』","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"你肯连补两件，他暖。清简的官身，因你这一针一线，竟有了私密的暖。","source":"宋官服尚简，见《宋史·舆服志》。"},{"text":"叹『穷进士，衣都穿不起』","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你一句穷，他笑意淡。他磨的是志不是穷，你错看了，便伤了他傲骨。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"官服"},{"id":"F-037-未","branch":"F","stage":3,"day":37,"shichen":"未时","checkpoint":"补官服","scene":"绣儿笑：『小姐绣那『盈』字，姑爷今早摸了半日，问我可瞧见。』你针一歪，耳热：『他倒细。』绣儿：『姑爷说，这是他穿过最体面的衣。』","options":[{"text":"低头笑『那我往后，多绣几件』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你应了多绣，绣儿乐。他珍那字，你便肯多给——盲婚的甜，原在这来往上。","source":"宋妇功传情，见《东京梦华录》。"},{"text":"嗔『叫他莫对外人说』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你害臊禁他声张，他未必说破，倒显得你小气。私密的心意，原该两人共享。","source":"同上。"}],"difficulty":2,"npc":["绣儿"],"foreshadow":"官服"},{"id":"F-037-戌","branch":"F","stage":3,"day":37,"shichen":"戌时","checkpoint":"补官服","scene":"戌时他披上补好的衣，忽然转一圈：『可还齐整？』你笑他孩子气。他正色：『盈儿缝的，齐整不齐整，都是顾景行最珍的衣。』灯下两人都弯了眼。","options":[{"text":"笑『那以后，你的衣都归我缝』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":1},"feedback":"你一句包揽，他笑纳。清官家的烟火，原是妻子一盏灯、丈夫一件衣，慢慢煨出来的。","source":"宋夫妇相偕，见笔记。"},{"text":"伸手替他抚平领口『莫骄傲，是衣该齐整』","correct":true,"tags":["感情","自主"],"dims":{"自主":1},"feedback":"你替他理领，也理他那点得意。能这般自然地近身，盲婚早成了寻常夫妻。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"官服","flavor":true},{"id":"F-038","branch":"F","stage":3,"day":38,"shichen":"辰时","checkpoint":"新婚","scene":"晨起他案上摊着未写完的奏稿，你顺手替他理齐，发现页边小字：『吾妻阿盈，喜酸，宜林檎。』你怔住——他连这都记在公事旁。","options":[{"text":"不动那行字，只把奏稿叠好","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你护着他私写的小字，他回头瞧见，眼软。最深的甜，是公事边角，也给你留了位。","source":"宋士人亲笔小注，见笔记。"},{"text":"笑他『公事上也写这个』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你打趣出声，他忙掩了。那行字是他藏的柔，你一笑嚷，倒叫他不好意思。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"书"},{"id":"F-038-未","branch":"F","stage":3,"day":38,"shichen":"未时","checkpoint":"新婚","scene":"绣儿收拾书房，嘀咕：『姑爷这屋，如今多了小姐的纸笔，还有那串林檎核，当宝贝收着呢。』你听得，忍不住去翻他抽屉，果然见核在锦囊。","options":[{"text":"轻轻把锦囊放回原处『由他收着』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你放回锦囊，也放回一份懂。他收果核，你收他的收，这桩缘，两头都惜。","source":"宋人以小物寄情，见笔记。"},{"text":"取笑他『酸儒，连核都留』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你取笑，他若知，必讪讪。那核是他笨拙的珍重，你笑轻了，他便不敢再藏。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"书"},{"id":"F-038-戌","branch":"F","stage":3,"day":38,"shichen":"戌时","checkpoint":"新婚","scene":"戌时他搁笔，似想说什么又止。你问，他笑：『明儿你便知。』你瞥见他案上压着张纸，墨痕才写半阕，像是词。你没去碰，只记在心里。","options":[{"text":"不偷看『你既说明日，我便等』","correct":true,"tags":["感情","自主"],"dims":{"自主":1,"情缘":1},"feedback":"你肯等，他不慌。明日的半阕，原要两人凑成——你这一等，便等来了唱和的开头。","source":"宋夫妻唱和之雅，见宋代笔记。"},{"text":"趁他不在，偷掀那张纸","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你手痒偷看，虽是好意，却坏了他预备的趣。唱和贵在相和，你先掀，便少了回味。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"半阕词"},{"id":"F-039","branch":"F","stage":4,"day":39,"shichen":"辰时","checkpoint":"诗书唱和","scene":"他出门前，案上压着半阕词：『小窗疏雨润青梅，酸透盈盈两道眉。』下阕空着。他留笺：『阿盈若闲，试补一二。』你看着那『盈盈』，心跳漏一拍。","options":[{"text":"提笔蘸墨，想了想，写下『却把甜时寄与谁』","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"你接了他的酸，还他一味甜。半阕补成全阕，盲婚的头一回唱和，竟这样自然。","source":"宋夫妻词赠答，见苏轼词序及宋代笔记。"},{"text":"搁着不写『我哪会作词』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你谦说不会，纸空着。他回来必失望——他递的是邀，你拒的也是，缘分差这一和。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"半阕词"},{"id":"F-039-未","branch":"F","stage":4,"day":39,"shichen":"未时","checkpoint":"诗书唱和","scene":"绣儿见你写词，惊奇：『小姐竟会这个？姑爷若见，不定多欢喜。』你红着脸把纸压好：『莫声张，等他回来看。』指尖还沾着未干的墨。","options":[{"text":"含笑『欢喜不欢喜，看他眼底』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你藏不住雀跃，绣儿笑。唱和是两人的秘密，你肯等他回来揭，便是甜的上半。","source":"宋闺秀能词者众，见《东京梦华录》。"},{"text":"慌道『快替我撕了，莫叫他笑我』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你怯场要撕，绣儿拦住。那阕词是他邀的，你撕了，倒拂了他一片心。","source":"同上。"}],"difficulty":1,"npc":["绣儿"],"foreshadow":"半阕词"},{"id":"F-039-戌","branch":"F","stage":4,"day":39,"shichen":"戌时","checkpoint":"诗书唱和","scene":"他归家，见补全的词，怔了许久，轻声念：『却把甜时寄与谁——阿盈，这甜，自然寄与我。』你低头，却见他耳根，也红透了。","options":[{"text":"抬眼笑『既寄了，你可接稳』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":2},"feedback":"你接了他的话，也接了这段缘。第一阕唱成，往后《唱和集》里，便有你一笔。","source":"宋以词唱和，见宋代笔记。"},{"text":"羞得跑开『谁寄你，胡念』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你害羞跑开，他愕然。甜已递到跟前，你偏逃，倒叫他摸不着深浅。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"半阕词"},{"id":"F-040","branch":"F","stage":4,"day":40,"shichen":"辰时","checkpoint":"诗书唱和","scene":"他铺开新纸：『既和了一阕，不如立个规矩——往后你我，有句便写在案上，压在砚台下，凑成了，便收进一本子里。』你望着那方旧砚。","options":[{"text":"点头『那本子，便叫《程顾唱和集》』","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"你给本子起了名，他击节。盲婚哑嫁走到这，竟有了两人共有的书——比金玉牢。","source":"宋人夫妇唱和结集者多有，见宋代笔记。"},{"text":"敷衍『随你高兴便好』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你淡应，他笔一顿。他要的是与你共一本，你随口，便轻了这番郑重。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"砚台"},{"id":"F-040-未","branch":"F","stage":4,"day":40,"shichen":"未时","checkpoint":"诗书唱和","scene":"他研墨，你执笔，两人同写一阕。他写上句你写下句，墨香混着林檎的酸气。砚台压着昨夜的词，阳光透过窗纱，照见两人交叠的影。","options":[{"text":"就着他的墨，补完最后一句","correct":true,"tags":["才华","感情"],"dims":{"才华":1,"情缘":1},"feedback":"你借他的墨收尾，他笑着看你。唱和之美，不在词工，在两人愿共用一方砚。","source":"宋人唱和，见宋代笔记。"},{"text":"另研一砚『我自写我的』","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你另起一砚，他讪讪。唱和原要共墨，你一分，便少了那股缠绵的暖。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"砚台"},{"id":"F-040-戌","branch":"F","stage":4,"day":40,"shichen":"戌时","checkpoint":"诗书唱和","scene":"戌时，你把他新写的半阕压在砚台下，自己也对了下半阕，轻轻压上。他来收纸，见两纸相叠，笑：『阿盈，往后这砚台，便是咱俩的约。』灯下两制墨香。","options":[{"text":"笑『约便约，谁先懒，谁认罚』","correct":true,"tags":["感情","情缘"],"dims":{"情缘":1},"feedback":"你定下罚约，他应了。盲婚哑嫁熬出的甜，原是一砚、一词、一约，慢慢把生人酿成熟人。","source":"宋夫妇以砚为契，见笔记。"},{"text":"伸手覆上他的手『那这约，盖了印』","correct":true,"tags":["感情","自主"],"dims":{"自主":1},"feedback":"你覆手为印，他反握。一方旧砚压着两阕词，也压着两颗，终于肯靠近的心。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"砚台","flavor":true},{"id":"F-041","branch":"F","stage":4,"day":41,"shichen":"辰时","checkpoint":"砚下词笺","scene":"晨起理砚，见你昨日压在砚下的半阕词旁，又多了几行墨迹。顾景行留了上片，末句空着等你。窗光斜过书案，茶烟尚温未散。","options":[{"text":"提笔续成下片，与他并案而书。","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"他搁笔看你，唇角微扬。案上两行并立，像两人并着肩。从此每日词笺都留一处等你来填，唱和成了你们两人的事。","source":"宋代夫妇唱和之雅，见宋代笔记。"},{"text":"把词笺收进匣中，待他自来取。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"词笺静静躺着，他傍晚才看见，笑着摇头。唱和要趁兴，你却把它收成了待办，错过了并案的好辰光。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"《唱和集》"},{"id":"F-041-未","branch":"F","stage":4,"day":41,"shichen":"未时","checkpoint":"家用账册","scene":"午后你翻他书房的家用账，见墨迹潦草、数目参差。顾景行揉额苦笑：这些向来他随手记，总对不齐。你指尖点过一笔笔开销出入。","options":[{"text":"取算筹重新厘算，将出入分作两栏。","correct":true,"tags":["才华","情缘"],"dims":{"情缘":1},"feedback":"他在一旁看着你拨算筹，眼里有惊也有暖。原来家中其余事也可托付于你，不独是词笺上的那点功夫。","source":"宋代士大夫家计，见《东京梦华录》。"},{"text":"由他糊涂去，莫要多事。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"账册照旧乱着，他月底对不上数直叹气。你本可露一手，却把本事藏了起来，家用事总差着一口气。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-041-戌","branch":"F","stage":4,"day":41,"shichen":"戌时","checkpoint":"灯下闲坐","scene":"戌时灯暖，他抄完公文，递来一盘炒银杏。你说起幼时在家也爱就灯剥果子，他停箸，似在听你少时说过的那些旧话。","options":[{"text":"与他就灯分食，慢慢讲些旧事。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"灯花爆了一下，你们一递一颗。旧事说尽，夜也深了，却像比白日近了些，檐下的雨声都轻了。","source":"宋代夜话之风，见宋代笔记。"},{"text":"吃过便歇，不必多言。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你早早阖眼，他吹灯时顿了顿。近要靠说，你却把话咽了回去，两个人的夜话只你一人听了。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-042","branch":"F","stage":4,"day":42,"shichen":"辰时","checkpoint":"续笺成册","scene":"你续的词笺又添两张，案头已积厚厚一叠。顾景行用青丝绳将词笺拢作一册，题了封面，搁在砚边等你来填下头的空。","options":[{"text":"在册尾也题一行，与他笔迹并排。","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"两行小字挨着，他看了半日，说这册子往后日日要添。唱和成了你们两人的事，谁也不先搁笔。","source":"宋代夫妇唱和之雅，见宋代笔记。"},{"text":"只由他题，自己不落墨。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"册子是他的字，你始终没落一笔。后来翻起，倒像你只是个看客，没真正走进这册子里。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"《唱和集》"},{"id":"F-042-未","branch":"F","stage":4,"day":42,"shichen":"未时","checkpoint":"回门备礼","scene":"三朝后你将回门，顾景行问想带什么。你说娘家爱吃汴京的蜜煎金橘，他即唤小厮去州桥老铺寻正宗的来，又问还念什么。","options":[{"text":"陪他一同挑礼，说娘家常念的旧物。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他一一记在笺上，说既嫁了，你娘家便是两家。回门礼备得周到，娘见了欢喜，你也觉脸上有光。","source":"宋代婚俗回门，见《东京梦华录》。"},{"text":"随他办，自己不管。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"礼虽齐备，却少了几样娘家真正念的。你没说，他也不知，回乡时话头便略生疏了些。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-042-戌","branch":"F","stage":4,"day":42,"shichen":"戌时","checkpoint":"檐下听雨","scene":"夜来微雨，檐角滴答。他披衣起，说怕你夜里凉，把外衫搭在你榻边。你握着还带余温的衣角，听见他回案边研墨。","options":[{"text":"披衣起身，给他添一盏热茶。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他接茶时怔了怔，随即笑了。雨声里两人各执一事，却比同榻更觉安稳，体贴原是这般来回的。","source":"宋代闺中日常，见宋代笔记。"},{"text":"由他忙，自己安睡。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你睡了，他独自研墨到夜深。体贴要回，你却只受了，不曾应一声，到底隔了一层薄纱。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-043","branch":"F","stage":4,"day":43,"shichen":"辰时","checkpoint":"同年帖至","scene":"同年宴的帖子到了，顾景行指着上头一个名字说，此人最善打趣。你笑说怕什么，他摇头，说你且看罢了，话里藏着几分在意。","options":[{"text":"说横竖有你在，不怕人笑。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他眉眼松了，把你这话记在帖角。有你撑着，同年间的热闹倒成了趣，他心里先踏实了半分。","source":"宋代同年之谊，见《梦粱录》。"},{"text":"劝他少去应酬，省得心烦。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他依言推了，却闷了一日。同年是士人常情，你替他避了，反显得生分，他那点依赖也无处落。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-043-未","branch":"F","stage":4,"day":43,"shichen":"未时","checkpoint":"帖角小字","scene":"宴前你替他理衣，发现帖角真添了你的那句。他耳根微红，说怕忘了你这份仗义。镜里两人并立，你替他整了整幞头。","options":[{"text":"伸手替他抚平衣领，目送出门。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他出门几步又回头，你立在阶上，他这才安心去了。小字压在帖角，也悄悄压进了彼此的心里。","source":"宋代同年之谊，见《梦粱录》。"},{"text":"只叮嘱早归，不近身。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"他独自去了，你未送。体贴在嘴边，没落到手上，到底隔了一层，他回头时阶上空荡荡的。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-043-戌","branch":"F","stage":4,"day":43,"shichen":"戌时","checkpoint":"灯前并坐","scene":"戌时他微醺归来，不急着卧，拉你在灯前并坐。他说今日有人打趣，他没恼，因想起你说横竖有你在。灯下他握了你手。","options":[{"text":"由他握着，也回握过去。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"两双手交着，灯花静静。你不必多言，他已知你应了那份仗义，这一夜比旁的都暖些。","source":"宋代夫妻夜话，见宋代笔记。"},{"text":"笑他醉了，却未抽手。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他说没醉，只是今日想牵你。你笑骂一句，手却由他攥了一夜，醉没醉，灯下的人都清楚。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"《唱和集》","flavor":true},{"id":"F-044","branch":"F","stage":4,"day":44,"shichen":"辰时","checkpoint":"小误将生","scene":"同年宴上果有人笑他「榜下被捉去的进士」，他只低头吃菜，不接话。你远远看着，心头忽地刺了一下，筷箸顿了顿。","options":[{"text":"下宴便去问他方才为何不语。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你没装作没事，径去问。肯问，便是把他的心事当了你的。他后来松了口，把实话缓缓道来。","source":"宋代同年宴饮，见《梦粱录》。"},{"text":"当没听见，回去各睡各的。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你忍了一路，他也不知你恼。误会最怕不开口，夜里两人背对着背，那点刺便发了芽。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-044-未","branch":"F","stage":4,"day":44,"shichen":"未时","checkpoint":"默而不语","scene":"归途他仍沉默，你心下越想越偏：莫非他真觉这桩亲事是被人捉来的，故而懊恼。轿帘垂着，你攥紧了帕子。","options":[{"text":"捺住多心，等他愿说时再听。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你把帕子松开，想他平日不是含糊人。先信他，才有后来那番剖白，疑心最误的是自家。","source":"宋代同年宴饮，见《梦粱录》。"},{"text":"先入为主，认定他悔了亲。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你越想越实，连他递的水都推开。疑心一旦生根，便听不进真话了，夜里的刺越扎越深。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-044-戌","branch":"F","stage":4,"day":44,"shichen":"戌时","checkpoint":"灯下剖白","scene":"夜深他忽坐起，说那日你多心了，他本该早讲。你说你确是多心，却也是因在意。灯影里两人都笑了，方才的刺没了。","options":[{"text":"说破便好，往后不积压。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他应了，说往后再不闷着。小误会是缝，说开了，反倒把两人缝得更紧，再小的刺也化作了暖。","source":"宋代夫妻相处，见宋代笔记。"},{"text":"说罢了，仍记在心里。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你嘴上说好，心里却留了痕。疙瘩不化，下次还疼，那点刺终是没真正拔干净。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-045","branch":"F","stage":4,"day":45,"shichen":"辰时","checkpoint":"实情始陈","scene":"他道放榜那日，人潮里他先瞧见的是茶棚帘后的你——执盏低头，像一幅静画。被捉上马，实是他顺水推舟，早存了心。","options":[{"text":"听着，把那日的自己也想起。","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"原来捉婿那日，他早先看见了你。你笑着去想帘后的自己，这事忽然甜了，孤身那日原是伏笔。","source":"宋代榜下捉婿，见《东京梦华录》。"},{"text":"笑他编故事讨欢喜。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你当趣话听，他也不辩。可那是真心话，你一哂，便错过去了，伏笔没接着，倒可惜了。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":null},{"id":"F-045-未","branch":"F","stage":4,"day":45,"shichen":"未时","checkpoint":"茶棚旧影","scene":"他说那茶棚如今还在州桥边，棚主记得你那日点的蜜煎。你心动，说改日要去谢那碗茶。他记下，说陪你同去走一遭。","options":[{"text":"约他改日同去那茶棚坐坐。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"两人记下了这桩小事。后来真去，棚主笑说早知道你俩有缘，一碗茶竟牵出这许多后话。","source":"宋代榜下捉婿，见《东京梦华录》。"},{"text":"说不必，自己去便罢。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你独自去了，回头他却失落。有些地方，要两个人走才成故事，你一人去，茶味便淡了半分。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"茶棚"},{"id":"F-045-戌","branch":"F","stage":4,"day":45,"shichen":"戌时","checkpoint":"砚边旧笺","scene":"你翻出压砚的那半阕，他凑近看，说那日便是这首引他留了心。你将词笺抚平，与他并排压好，像定了一件旧盟约。","options":[{"text":"与他将旧笺一并收入《唱和集》。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"半阕词成了册里第一页。往后每添一张，都从这一日算起，砚边的盟约也算落了实。","source":"宋代唱和，见宋代笔记。"},{"text":"仍压砚下，不收册。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"笺子压着，久了边角卷了。好物要收，你却让它蒙尘，那点盟约也跟着旧在了砚下。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"《唱和集》"},{"id":"F-046","branch":"F","stage":4,"day":46,"shichen":"辰时","checkpoint":"托付家用","scene":"他说书房账总对不齐，索性把家用全交你理。铜钥匙并一册总账放你面前，说往后出入由你作主，莫再让他糊涂。","options":[{"text":"接了钥匙，当夜便理清总账。","correct":true,"tags":["才华","情缘"],"dims":{"情缘":1},"feedback":"你拨算筹到三更，数目齐齐。他晨起看见，放心也欢喜——家事交给了妥当人，他也松了肩。","source":"宋代主家理财，见《东京梦华录》。"},{"text":"推说不会，仍还他。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"钥匙退回，他只好自己应付。你本露得一手，却把信任推了回去，两人都少了那层托付。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-046-未","branch":"F","stage":4,"day":46,"shichen":"未时","checkpoint":"井臼亲理","scene":"你核完米肉瓜果的价，吩咐厨房照新单办。仆从见你井井有条，私下说新妇虽小，管家倒利落。这话传到婆母耳里。","options":[{"text":"照单行事，不骄不矜。","correct":true,"tags":["才华","情缘"],"dims":{"情缘":1},"feedback":"你安然理家，不显能。婆母看在眼里，挑剔少了三分，清严的人最认的是这份沉得住气。","source":"宋代主家理财，见《东京梦华录》。"},{"text":"听见夸便张扬。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你露出得意，婆母反蹙眉。露才要敛，一扬便惹嫌，前头积的几分好感也打了折。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-046-戌","branch":"F","stage":4,"day":46,"shichen":"戌时","checkpoint":"婆母试探","scene":"婆母唤你去，问米价几何、冬衣几领。你对答如流，她点点头，没再挑剔，只说景行自幼不会算，往后劳你多费心。","options":[{"text":"温言应下，说该当的。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"婆母第一次正眼看你，将钥匙又添了一把。清严的人，认的是本事，你一回话便软了三分。","source":"宋代婆媳，见宋代笔记。"},{"text":"暗自得意，回房说嘴。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你回房炫耀，被婆母知了，脸色又冷。分寸要紧，一飘就前功尽弃，钥匙又攥回她手里。","source":"同上。"}],"difficulty":1,"npc":["顾景行","顾夫人"],"foreshadow":null},{"id":"F-047","branch":"F","stage":4,"day":47,"shichen":"辰时","checkpoint":"雨信将至","scene":"连阴了三日，婆母说你三朝回门那日怕要落雨。顾景行望着天，说那日他定去接。你笑他娇惯，他说不是娇，是怕你淋。","options":[{"text":"由他记挂着，心里暖。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你没嫌他啰嗦，只觉被人惦记是好事。雨还没下，心先湿了一角，那点暖比伞还先到了。","source":"宋代风雨相送，见宋代笔记。"},{"text":"说不必，自己有脚。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你逞能，他讪讪收了话。可他真想接，你一推，把心意也推远了，雨里便真只剩你一人。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"雨夜的伞"},{"id":"F-047-未","branch":"F","stage":4,"day":47,"shichen":"未时","checkpoint":"伞备阶前","scene":"他真找出一柄油绢伞搁在门边，说回门那日带着。伞骨是他旧年用的，你试撑开，闻见淡淡墨味，像他身上的。","options":[{"text":"收下伞，也替他理好衣襟。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"伞归你，你替他整衣。两人各做一件小事，倒比说许多话都亲，那柄伞也染了你们两人的气。","source":"宋代风雨相送，见宋代笔记。"},{"text":"说用不着，搁回去。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"伞收回去，他闷了闷。你嫌麻烦，却不知他备了半日，那点墨味里藏的都是他的心思。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"雨夜的伞"},{"id":"F-047-戌","branch":"F","stage":4,"day":47,"shichen":"戌时","checkpoint":"雨夜相候","scene":"戌时雨落，你回门迟归。远远见榜下巷口立着一人执伞，正是他。见轿来，他快步迎上，把伞全倾向你这边。","options":[{"text":"下轿由他扶，伞下靠他肩。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"半边肩湿了，他浑不在意。你第一次觉出，被人接是这般踏实，雨夜的灯也因他暖了。","source":"宋代雨中相候，见宋代笔记。"},{"text":"笑他傻，却把伞往他那边推。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你推伞给他，两人都湿了袖。他说宁可湿透，也不让你沾雨，那柄伞下挤着两颗心。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"雨夜的伞","flavor":true},{"id":"F-048","branch":"F","stage":4,"day":48,"shichen":"辰时","checkpoint":"回门余温","scene":"雨夜归后，你娘家捎话，说顾郎撑伞来接的模样，娘看了直念好。你展信给景行看，他耳根又红了，低头抿茶。","options":[{"text":"把信递他看，由他羞去。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他看了信半天不言语，只笑。娘家一句好，比万千夸都重，也替他在你家里落了实。","source":"宋代回门，见《东京梦华录》。"},{"text":"自己收着，不给他看。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"信你藏了，他不知娘家赞他。好话该传，你却咽下，反倒生分，他少了一桩欢喜。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-048-未","branch":"F","stage":4,"day":48,"shichen":"未时","checkpoint":"伞上墨痕","scene":"那柄伞晾干，你见伞骨里侧有他早年的小字，写的是放榜前一夜的心事。你摩挲着，想起他孤身那日的来由。","options":[{"text":"把伞好好收着，当件念物。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"伞成了你们之间的旧物。后来每落雨，都想起巷口那盏斜斜的灯，和他半湿的肩。","source":"宋代风雨相送，见宋代笔记。"},{"text":"随手搁回杂物处。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"伞丢在角落，再找时骨裂了。有心的物件要惜，你却随手了，那段心事也跟着裂了缝。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"雨夜的伞"},{"id":"F-048-戌","branch":"F","stage":4,"day":48,"shichen":"戌时","checkpoint":"伏笔将收","scene":"你想起他放榜孤身、婉拒高门的由头，似与这伞上小字有关。问他，他说不急，待你把《唱和集》填满了，自然知晓。","options":[{"text":"不催，安心把册子填下去。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你信他，慢慢填册。伏笔要沉得住，他既说会讲，便值得等，急出来的实话总少了滋味。","source":"宋代笔记逸闻。"},{"text":"缠着问个明白。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你追着问，他无奈岔开。心事有时机，逼出来便不是原味了，那点由头也失了分量。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-049","branch":"F","stage":4,"day":49,"shichen":"辰时","checkpoint":"钥匙交托","scene":"婆母使人唤你，将库中最后一把钥匙并田庄租契一并交来，说景行自幼不管这些，往后你俩合计着办，莫让她操心。","options":[{"text":"双手接过，说记下了。","correct":true,"tags":["才华","情缘"],"dims":{"情缘":1},"feedback":"钥匙落你手心，沉甸甸。婆母终肯托付，是真心认了你这个媳，清严人的一句记下重千钧。","source":"宋代主母持家，见《东京梦华录》。"},{"text":"推说年轻担不动。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你推了，婆母收回手。信任递到门前，你却不敢接，那把钥匙又回到了她袖中。","source":"同上。"}],"difficulty":1,"npc":["顾景行","顾夫人"],"foreshadow":null},{"id":"F-049-未","branch":"F","stage":4,"day":49,"shichen":"未时","checkpoint":"契上朱印","scene":"你展租契核对佃户姓名，发现一笔旧账与他说的对不上。你不动声色记下，打算晚间与他慢慢盘，不当着人面声张。","options":[{"text":"记着，晚间平和与他核对。","correct":true,"tags":["才华","情缘"],"dims":{"情缘":1},"feedback":"夜里两人对契，错处一一厘清。他服你精细，也更信你持家，家事便真交到你手里了。","source":"宋代主家理财，见《东京梦华录》。"},{"text":"当众点破，让他下不来台。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你当众揭短，他脸上挂不住。账要对，却不该在人前折他，夫妻失和便从这一句起。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-049-戌","branch":"F","stage":4,"day":49,"shichen":"戌时","checkpoint":"灯下对账","scene":"灯下你们并算租入，他忽然说，原来家里有你，他才算真有了家。你笔尖一顿，没抬头，却轻轻应了一声。","options":[{"text":"应他，也把自己算进这家。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"一笔账算成了两口子。他说的不错，有你，书房才像家，那声应比许多盟誓都沉。","source":"宋代家计，见宋代笔记。"},{"text":"只埋头算，不接话。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你沉默，他讪讪住了口。近一步的话，你没接，又退回丈外，那点暖便凉在算筹上。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-050","branch":"F","stage":4,"day":50,"shichen":"辰时","checkpoint":"唱和成册","scene":"《唱和集》已厚厚一册，你数了数，整四十张。他笑说恰是放榜至今的日子，一日一张，一张一人一句，竟暗合了。","options":[{"text":"在册首题记，记下起意那日。","correct":true,"tags":["才华","情缘"],"dims":{"情缘":1},"feedback":"你题了「榜下砚边始」，他看了久久。一册词，原是你们一步步走近的痕，落了根便忘不了。","source":"宋代唱和集，见宋代笔记。"},{"text":"说不过闲戏，不必题记。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"册子没头没尾，后来翻起，倒想不起从哪日始。好物该留根，你一略，册子便轻了。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"《唱和集》"},{"id":"F-050-未","branch":"F","stage":4,"day":50,"shichen":"未时","checkpoint":"婆母设宴","scene":"婆母破例为你摆小宴，请了两位族中婶娘，说你理家有方。席间她第一次替你布菜，旁人看在眼里，知你立住了。","options":[{"text":"起身为婆母敬一盏，谢她教诲。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你敬得妥帖，婆母眉开。清严之人最重礼，你一回，她便软了，满座也知你得了正眼。","source":"宋代婆媳之礼，见《东京梦华录》。"},{"text":"受之泰然，毫不谦让。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你安然受着，婶娘们倒议论新妇傲。礼数缺一处，前头功夫折半，婆母的笑也淡了。","source":"同上。"}],"difficulty":2,"npc":["顾景行","顾夫人"],"foreshadow":null},{"id":"F-050-戌","branch":"F","stage":4,"day":50,"shichen":"戌时","checkpoint":"月下闲步","scene":"宴散月好，他陪你在院里走，说自榜下那日，就没想过旁人。你踩着月影，忽然觉这一程走得值，风也软了。","options":[{"text":"与他并影而行，不语也安。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"两道影子叠着，你忽然懂了何谓良缘。不必说破，月知道，风也知道，你们都知道了。","source":"宋代庭院闲步，见宋代笔记。"},{"text":"说夜凉，先进屋。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你先进了，他立在月下许久。好景要同看，你却先走，漏了一步，那点默契也短了。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":null},{"id":"F-051","branch":"F","stage":5,"day":51,"shichen":"辰时","checkpoint":"文集序意","scene":"他伏案整自己的文集，你瞥见序里引了你那半阕词，却未署名。你问他，他笑说留着，等满了再署你的名，不急。","options":[{"text":"由他引着，也添一句在序旁。","correct":true,"tags":["才华","情缘"],"dims":{"情缘":1},"feedback":"你的小字落进他文集序，像名分先落了半边。含蓄人的心迹，藏在字里，比说破还重。","source":"宋代文人序跋，见宋代笔记。"},{"text":"说不宜，让他删去。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你嫌唐突，他依言划了。可那是他肯认你的证，你一划，痕迹没了，序旁也空了。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"文集序"},{"id":"F-051-未","branch":"F","stage":5,"day":51,"shichen":"未时","checkpoint":"序旁小字","scene":"他真在序旁空出一块，说待你应了，再补姓名。你用指甲在空处轻轻划了道印，他见了，笑说这是先盖的章。","options":[{"text":"由那道印留着，算你应了。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"无形之印盖了，他欢喜。宋代人的应允不必锣鼓，一道指甲痕足够，名分便先定下半边。","source":"宋代文人序跋，见宋代笔记。"},{"text":"说玩笑，抹平了那印。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你抹平了，他笑意淡了。近一步你退一步，他也不好再逼，那道印便真成了玩笑。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"文集序"},{"id":"F-051-戌","branch":"F","stage":5,"day":51,"shichen":"戌时","checkpoint":"心照不宣","scene":"戌时他读文集给你听，读到序那句，停了，望你。你不言，只把茶递过去。两下都懂，那半阕早成了两人的序。","options":[{"text":"递茶时指尖轻触他手。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"一触即收，他却记了一夜。心照不宣最甜，不必说破，那半阕词早已是你们两人的序。","source":"宋代夫妻唱和，见宋代笔记。"},{"text":"笑说这序该署你两个的名。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他朗声应好，当即空处补了「程氏阿盈」。名分落定，你不躲了，序旁那行字也圆了。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"文集序","flavor":true},{"id":"F-052","branch":"F","stage":5,"day":52,"shichen":"辰时","checkpoint":"金榜旧页","scene":"他自书笥深处翻出一页泛黄红纸，说是从当年金榜上小心揭下的。纸边卷了，墨色却还清——上头有他的名，朱印犹红。","options":[{"text":"与他并看那页，听他讲当年。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"旧榜摊开，他指自己名给你看。从前的光，如今照着你们俩，那页红纸也添了归处。","source":"宋代金榜，见《东京梦华录》。"},{"text":"说旧纸罢了，不必看。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你没瞧，他默默收起。那是他的来路，你一略过，他便孤了些，红纸又回了笥底。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"红纸榜文"},{"id":"F-052-未","branch":"F","stage":5,"day":52,"shichen":"未时","checkpoint":"姊妹篇彩蛋","scene":"他翻到纸背，竟有他早年小字：『嘉祐二年春，我中了；后来你嫁了。』你怔住——这页他竟早留了你的位置。","options":[{"text":"笑他早就算定，也把这句抄进册。","correct":true,"tags":["情缘"],"dims":{"情缘":2},"feedback":"你抄进《唱和集》，两页遥遥相应。同宇宙的小彩蛋，甜在早有伏笔，红纸与词册从此并着。","source":"联动姊妹篇《我在宋朝会状元及第吗》，见宋代笔记。"},{"text":"说后人看了要笑。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你笑他痴，没抄。可那是他给你的座次，你一哂，空了那行，彩蛋也少了一笔呼应。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"红纸榜文"},{"id":"F-052-戌","branch":"F","stage":5,"day":52,"shichen":"戌时","checkpoint":"红纸藏匣","scene":"他将那页红纸与你那半阕词并藏一匣，说往后传家，先给人看这张榜，再看这册词。你合上匣盖，像合上一桩因果。","options":[{"text":"由他藏，也添一缕你发的红线。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"一缕红线压在匣里，旧榜新词系作一处。他说的传家，你应了，匣中也算落了你们两人的印。","source":"宋代传家旧俗，见宋代笔记。"},{"text":"说不必这么重。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你觉得言重，没添。他讪讪，原想与你共一桩念想，你却轻了，匣里也只他一人的痕。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"红纸榜文"},{"id":"F-053","branch":"F","stage":5,"day":53,"shichen":"辰时","checkpoint":"相国寺肆","scene":"休沐他带你逛相国寺书肆，说要为你寻本《花间集》的善本。摊主熟识，笑说顾官人每月都来问新到的词选。","options":[{"text":"由他挑，也翻一本与他看。","correct":true,"tags":["才华","情缘"],"dims":{"情缘":1},"feedback":"你回挑一本给他，他珍重收着。书肆成了你们的公地，每月都来，汴京的喧阗里有了定处。","source":"宋代相国寺集市，见《东京梦华录》。"},{"text":"说随便，自去别处。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你走开，他一人挑。同行不同步，倒像各逛各的，书肆的热闹也少了陪你的一份。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-053-未","branch":"F","stage":5,"day":53,"shichen":"未时","checkpoint":"肆中拾遗","scene":"你在故纸堆里翻出半张残笺，墨迹像极你幼时临的帖。他凑来看，说原来你笔路早有根，难怪词对得妥。","options":[{"text":"把残笺也买了，与他同赏。","correct":true,"tags":["才华","情缘"],"dims":{"情缘":1},"feedback":"残笺归你，他笑说物各有主。你笔路的旧根，被他一眼认出，拾遗拾的也是旧缘。","source":"宋代相国寺集市，见《东京梦华录》。"},{"text":"说残破不要。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你弃了，他惋惜。有些旧物是缘，你随手，便错过了呼应，那半张帖也回了故纸堆。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-053-戌","branch":"F","stage":5,"day":53,"shichen":"戌时","checkpoint":"寺前分茶","scene":"寺前茶棚歇脚，他说这棚与他当年茶棚不同，却都因你停过步。你啜茶笑，原来两处茶香，都系着一个你。","options":[{"text":"与他分一盏，说两处都好。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"一盏茶两人分，他说往后逢茶棚都想起你。甜在处处有你影，两处茶香原是一脉。","source":"宋代相国寺集市，见《东京梦华录》。"},{"text":"自饮自的，不多话。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你自饮，他望着出神。好景当前，你却独享，漏了呼应，茶棚的闲也少了陪你的那缕。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-054","branch":"F","stage":5,"day":54,"shichen":"辰时","checkpoint":"州桥夜市","scene":"入夜他牵你去州桥夜市，说蜜煎金橘、团子、炙肉，挨个带你尝。灯球照得街如昼，人声里他护着你走，怕你被挤散。","options":[{"text":"由他牵着，挨样尝过去。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他一一喂你尝，像把汴京的甜都给你。夜市喧阗，你只看见他，灯球也成了陪衬。","source":"宋代州桥夜市，见《东京梦华录》。"},{"text":"说人多，自己看摊。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你脱了手乱看，他着急寻你。热闹里走散，便是憾，州桥的甜也因那一声喊淡了。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-054-未","branch":"F","stage":5,"day":54,"shichen":"未时","checkpoint":"灯球影里","scene":"灯球下他替你拢好披风，说州桥风大。你抬头，见他眼底映着灯，比灯还亮。卖花担子过，他顺手挑了支簪你髻上。","options":[{"text":"由他簪，也回赠他一枝。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他簪你，你回他一枝，旁人笑一对痴人。夜市里，你们是彼此的花，风也吹不散。","source":"宋代州桥夜市，见《东京梦华录》。"},{"text":"说不必，摘下放回。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你摘了，他讪讪。小礼是心，你一退，凉了那截暖，花担子过处也少了陪你的一枝。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-054-戌","branch":"F","stage":5,"day":54,"shichen":"戌时","checkpoint":"夜归并肩","scene":"夜市尽兴归，他仍牵着你，说今日比放榜那日还欢喜。你笑，放榜是你中，今日是咱俩。他没驳，只把你的手握紧。","options":[{"text":"由他握紧，慢慢走回去。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"手心的汗他也不松。你说得对，今日是咱俩的榜，州桥的灯一路送到家门还亮着。","source":"宋代州桥夜市，见《东京梦华录》。"},{"text":"说累了，催他快走。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你催，他松开手赶路。好夜要慢，一催，味就短了，州桥的余兴也断在脚步里。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-055","branch":"F","stage":5,"day":55,"shichen":"辰时","checkpoint":"伏笔将解","scene":"他近日常看那柄旧伞，你问起伞上小字说的事，他笑说《唱和集》将满，该告诉你放榜孤身的由头了，不日便讲。","options":[{"text":"由他择日讲，不急着催。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你沉得住，他更想讲。伏笔要等到恰好处，才显分量，那柄伞上的心事也值得郑重说。","source":"宋代笔记逸闻。"},{"text":"说现在就说。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你催，他只得草草。该郑重的由头，被你一句催浅了，伞上小字也失了那点沉。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"雨夜的伞"},{"id":"F-055-未","branch":"F","stage":5,"day":55,"shichen":"未时","checkpoint":"孤身之由","scene":"他说放榜那日他本已决意不赴高门之邀，只想慢慢挑个能唱和的人。茶棚帘后的你，正合了那句「慢挑」的心。","options":[{"text":"说原来你早替自己留了地。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你笑他迂，却懂他孤身是等为对的人。婉拒高门，原是等你，那页红纸旁早该有你。","source":"宋代榜下捉婿，见《东京梦华录》。"},{"text":"说他太挑，险些错过。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你笑他险，他低头。可他那日若从了高门，便没今日的册子了，挑也并非全错。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-055-戌","branch":"F","stage":5,"day":55,"shichen":"戌时","checkpoint":"旧由说尽","scene":"戌时他讲完，说婉拒高门非矫情，是信世间有能共砚的人。你听着，把伞上小字与他那日的话，轻轻叠在一处。","options":[{"text":"说你信他，也信这一程。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"伏笔收净，你全信了。他孤身那日，原是在等人的前夜，伞上小字也终于落了地。","source":"宋代婚恋逸闻，见宋代笔记。"},{"text":"把伞与他并放，算两段都圆了。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"旧伞新话并着，两段由头都圆。他说从此不必再瞒你半句，那点孤也彻底化了。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"雨夜的伞","flavor":true},{"id":"F-056","branch":"F","stage":5,"day":56,"shichen":"辰时","checkpoint":"百日将届","scene":"婆母掐指说成婚将满百日，该小小庆。他笑说不必铺张，只想与你回榜墙下走走，看看那日捉婿的地方，温一温旧。","options":[{"text":"应他，说也正想去看看。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"两人都惦着那面墙。百日不见，墙还在，人已不同，缘起地也该回去走一遭了。","source":"宋代榜下风俗，见《东京梦华录》。"},{"text":"说旧地何必重提。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你淡了，他讪讪。那墙是缘起，你一略，他失落，百日的圆也少了一个落脚处。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"红纸榜文"},{"id":"F-056-未","branch":"F","stage":5,"day":56,"shichen":"未时","checkpoint":"榜墙旧地","scene":"你们真去榜墙下，墙已无旧榜，只青砖斑驳。他指一处说那日你轿停这儿，他被推上马时，眼还往帘后瞟。","options":[{"text":"立他指处，想象那日的自己。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你立着笑，仿佛看见帘后的旧我。墙下的故事，你俩重讲一遍，青砖也记下了这回。","source":"宋代榜下风俗，见《东京梦华录》。"},{"text":"说都是从前，走罢。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你催走，他未尽兴。缘起地要慢看，一催便草草，那点温也随脚步散在风里。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"红纸榜文"},{"id":"F-056-戌","branch":"F","stage":5,"day":56,"shichen":"戌时","checkpoint":"墙下旧影","scene":"他忽然从袖里取出一张红纸——竟是当年榜墙揭下留存的半幅榜文，说一直收着，等今日带来给你瞧，风过纸响。","options":[{"text":"接了红纸，与他并看旧名。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"半幅榜文摊开，他的名还在。今日你站他身旁，名旁该添你了，墙下风里缘有了形。","source":"宋代榜下风俗，见《东京梦华录》。"},{"text":"说纸旧了，收好便是。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你没细看，他收起。他特地带的念想，你一略过，凉了，红纸又回了袖中独着。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"红纸榜文"},{"id":"F-057","branch":"F","stage":5,"day":57,"shichen":"辰时","checkpoint":"册将满页","scene":"《唱和集》只差最后几张便满百。他说明日休沐，要与你把末几张填了，凑个整。你笑着应，说那日该蘸好墨。","options":[{"text":"与他约好，备新墨填末页。","correct":true,"tags":["才华","情缘"],"dims":{"情缘":1},"feedback":"新墨备下，末页待填。一册将满，像你们将走完这程，砚边的事也有了妥妥的收束。","source":"宋代唱和，见宋代笔记。"},{"text":"说随便填填便罢。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你敷衍，他也不强求。收尾要郑重，一随便，册子少了魂，百日的圆也缺了角。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"《唱和集》"},{"id":"F-057-未","branch":"F","stage":5,"day":57,"shichen":"未时","checkpoint":"末页题名","scene":"你蘸饱墨，在末页落了两人名，旁题「榜下百年」。他看了，说这比金榜那页更让他欢喜——那是他一人，这是两人。","options":[{"text":"由他比，也把这句写进序。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"「一人榜」与「两人册」，他心里有了高低。你落笔，把喜写定，册子也真正圆了。","source":"宋代唱和，见宋代笔记。"},{"text":"说莫比，都是旧纸。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你打圆场，他笑淡。可他真想你认这本册重些，你一比没比，那点欢喜也淡了。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"《唱和集》"},{"id":"F-057-戌","branch":"F","stage":5,"day":57,"shichen":"戌时","checkpoint":"灯下展册","scene":"夜来你们并坐展册，从第一张读到末页，像把百日走了一遍。他忽然说，若重来一次，还愿被捉上那匹马。","options":[{"text":"笑说那便再被捉一回。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他大笑，说一言为定。册子合上，百日的甜都收在里面了，马背上的那步也值了。","source":"宋代唱和，见宋代笔记。"},{"text":"说莫胡言，早歇着。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你岔开，他噤了声。甜话要接，你一拦，气氛凉了，册子也只合到一半的暖。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"《唱和集》"},{"id":"F-058","branch":"F","stage":5,"day":58,"shichen":"辰时","checkpoint":"婆母赐礼","scene":"婆母唤你，赐一对并蒂银奁，说见你们唱和相宜，心里妥了。她少见地笑，说景行娶对的人，她便放心，也算是遂愿。","options":[{"text":"谢过婆母，说托她福。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你谢得周正，婆母愈喜。清严人肯笑，是真正认了你，并蒂奁也成了屋里的正经物件。","source":"宋代婆媳，见《东京梦华录》。"},{"text":"受之不谢，显平常。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你淡受，婆母眸色一沉。礼要谢，你一平，又远了，并蒂奁也像是客气的敷衍。","source":"同上。"}],"difficulty":1,"npc":["顾景行","顾夫人"],"foreshadow":null},{"id":"F-058-未","branch":"F","stage":5,"day":58,"shichen":"未时","checkpoint":"奁中双影","scene":"银奁里并放着你那半阕词与他引的那句，他笑说婆母竟也知你们的根。你将奁合好，说往后摆在内室案上。","options":[{"text":"把奁摆案上，当个念。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"奁立案头，日日见。婆母的认，成了屋里的景，那半阕词也终于摆在了明处。","source":"宋代婆媳，见《东京梦华录》。"},{"text":"说收匣便罢。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你收起，他微憾。好意该摆在明处，你一收，暗了，婆母那点笑也跟着收了。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":null},{"id":"F-058-戌","branch":"F","stage":5,"day":58,"shichen":"戌时","checkpoint":"院中并立","scene":"婆母走后，你们在院里并立，他说娘从不夸人，今日这话重。你笑，说那你便是她肯夸的媳婿了。他摇头，说夸的是你。","options":[{"text":"由他夸，也回夸他一句。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"两人互夸，像孩子。良缘里谁也不输那句好话，院里的风也跟着软和了下来。","source":"宋代婆媳，见《东京梦华录》。"},{"text":"说莫贫嘴，进屋去。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你截了，他笑住。好话要来回，你一断，短了半截，院里的暖也随你进了屋。","source":"同上。"}],"difficulty":1,"npc":["顾景行","顾夫人"],"foreshadow":null},{"id":"F-059","branch":"F","stage":5,"day":59,"shichen":"辰时","checkpoint":"放榜周年","scene":"算着正是放榜周年，他说那日孤身，今日身旁有人。你笑说一年前你还在茶棚，一年后在他身边。他点头，说值。","options":[{"text":"由他感慨，也道一年甘苦。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"一年从头数，甘多于苦。他孤身的那日，成了你们日的起点，周年回望也甜了大半。","source":"宋代同年忆旧，见《梦粱录》。"},{"text":"说过去事提它做甚。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你略过，他讪讪。周年要回望，你一略，他便孤了些，那点值也少人同证。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"红纸榜文"},{"id":"F-059-未","branch":"F","stage":5,"day":59,"shichen":"未时","checkpoint":"红纸重展","scene":"他取出那半幅榜文与金榜旧页并展，说两张都因你有了归处。你抚纸，说原来两张红纸，都系着一个顾景行。","options":[{"text":"把两张红纸一并收好，当传家。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"两纸归匣，像两段路并作一途。他说往后子孙看，先见榜再见你，红纸也认了主。","source":"宋代传家旧俗，见宋代笔记。"},{"text":"说纸脆，莫常展。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你收起，他微惜。念想要常看，你一护，倒少了温度，两张红纸也只在匣底躺着。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"红纸榜文"},{"id":"F-059-戌","branch":"F","stage":5,"day":59,"shichen":"戌时","checkpoint":"岁晏灯前","scene":"戌时岁晏，他握你手说，这一年最对的，便是榜下那步。你回握，说最对的，是砚边肯续那半阕的人。灯花并蒂。","options":[{"text":"说续阕的是你，捉婿的也是你。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"两人把功都推给对方，灯下笑作一团。良缘是互相认账，半阕词与那匹马都成了你们的。","source":"宋代夫妻夜话，见宋代笔记。"},{"text":"说往后再填它千张万张。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他说一言为定，册子往后无穷。一年太短，你们要写一辈子，灯花也并蒂到了岁尾。","source":"同上。"}],"difficulty":2,"npc":["顾景行"],"foreshadow":"红纸榜文","flavor":true},{"id":"F-060","branch":"F","stage":5,"day":60,"shichen":"辰时","checkpoint":"百日之约","scene":"成婚百日恰逢放榜周年，他早起说今日要去榜墙下走一遭，把那张留存的红纸榜文带上。你应了，替他整衣。","options":[{"text":"随他去，也把《唱和集》带上。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"册子随行，像把百日都带去。墙下旧地，今日要收个圆，砚边与榜下终于并到了一处。","source":"宋代榜下风俗，见《东京梦华录》。"},{"text":"说风大，改日再去。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你改期，他微憾。圆要有日，一推，又悬着，红纸与册子也还在匣里等着。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"《唱和集》"},{"id":"F-060-未","branch":"F","stage":5,"day":60,"shichen":"未时","checkpoint":"墙下展纸","scene":"榜墙下他展开那张留存红纸榜文，指自己名给你看，说一年前这名字孤着，一年后旁多了一个你。风过纸响。","options":[{"text":"立他身侧，与他同看旧名。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你立他旁，名旁仿佛真多了你。墙下风里，缘有了形状，那页红纸也等到了该等的人。","source":"宋代榜下风俗，见《东京梦华录》。"},{"text":"说纸旧，莫吹坏了。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你护纸，他笑。念想要看，你只护，倒没接那句，红纸旁仍只他一个名字晃着。","source":"同上。"}],"difficulty":1,"npc":["顾景行"],"foreshadow":"红纸榜文"},{"id":"F-060-戌","branch":"F","stage":5,"day":60,"shichen":"戌时","checkpoint":"榜下双收","scene":"戌时他收起红纸，说捉婿那日，他爹替他看的人，比他想的还好；你笑，榜下从来不只一条路，你选的这条，是对的。","options":[{"text":"说挂灯人原是爹替你挑的，挑得好。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你认下那桩「挂灯人」的缘。捉婿那日爹替你看的人，比你想象的好——这良缘，成了。","source":"宋代榜下捉婿，见《东京梦华录》。"},{"text":"说榜下路多，你走对的这条便值。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你认下自己选的路。榜下从来不只一条路，你选的这条是对的——答案，早就在你手里。","source":"同上。"}],"difficulty":3,"npc":["顾景行"],"foreshadow":"红纸榜文","finale":true}]